/**
 * JARVIS v20 — Finestra Principale
 * Layout: Sidebar + Stacked Views (4 viste)
 * Viste: 1. Live Dashboard, 2. Backtest & Analytics, 3. System Logs, 4. Settings
 */
import QtQuick
import QtQuick.Controls
import QtQuick.Layouts
import QtQuick.Window
import JarvisBackend 1.0
import "components"

ApplicationWindow {
    id: root
    width: 1600
    height: 960
    minimumWidth: 1280
    minimumHeight: 720
    title: "JARVIS v20 — Market Intelligence"
    visible: true
    flags: Qt.Window | Qt.WindowMinMaxButtonsHint | Qt.WindowCloseButtonHint

    readonly property Backend backend: Backend {}

    // Carica font locali
    FontLoader { id: fontUrbanist; source: "qrc:/fonts/Urbanist-Regular.ttf" }
    FontLoader { id: fontUrbanistMedium; source: "qrc:/fonts/Urbanist-Medium.ttf" }
    FontLoader { id: fontUrbanistBold; source: "qrc:/fonts/Urbanist-Bold.ttf" }
    FontLoader { id: fontSora; source: "qrc:/fonts/Sora-Regular.ttf" }
    FontLoader { id: fontSoraMedium; source: "qrc:/fonts/Sora-Medium.ttf" }
    FontLoader { id: fontSoraBold; source: "qrc:/fonts/Sora-Bold.ttf" }

    // ─── STILE GLOBALE ───
    Rectangle { anchors.fill: parent; color: Theme.bgPrimary }

    RowLayout {
        anchors.fill: parent
        spacing: 0

        // ─── SIDEBAR ───
        Rectangle {
            id: sidebar
            Layout.preferredWidth: 220
            Layout.minimumWidth: 208
            Layout.maximumWidth: 232
            Layout.fillHeight: true
            color: Theme.bgSurface
            border.color: Theme.borderPrimary
            border.width: 1

            ColumnLayout {
                id: sidebarLayout
                anchors.fill: parent
                anchors.margins: Theme.sp3
                spacing: Theme.sp2

                // Brand
                ColumnLayout {
                    Layout.fillWidth: true
                    spacing: 2

                    Text {
                        text: "JARVIS"
                        font: Theme.fontUI(Theme.fontXL, 700)
                        color: Theme.textPrimary
                        letterSpacing: 4
                    }
                    Text {
                        text: "v20"
                        font: Theme.fontMono(Theme.fontSM, 600)
                        color: Theme.info
                        letterSpacing: 2
                    }
                }

                // Separatore
                Rectangle {
                    Layout.fillWidth: true
                    height: 1
                    color: Theme.borderSecondary
                    Layout.margins: Theme.sp2
                }

                // Section label
                Text {
                    text: "NAVIGAZIONE"
                    font: Theme.fontUI(Theme.fontXS, 700)
                    color: Theme.textMuted
                    letterSpacing: 1
                    Layout.leftMargin: Theme.sp2
                }

                // Voci menu
                ColumnLayout {
                    Layout.fillWidth: true
                    spacing: 4

                    SidebarItem {
                        id: btnLive
                        icon: "▦"
                        text: "Dashboard Live"
                        viewId: "live"
                        selected: true
                        onClicked: stack.currentIndex = 0
                    }
                    SidebarItem {
                        id: btnBacktest
                        icon: "⌘"
                        text: "Analisi & Backtest"
                        viewId: "backtest"
                        onClicked: stack.currentIndex = 1
                    }
                    SidebarItem {
                        id: btnLogs
                        icon: "⌨"
                        text: "Log di Sistema"
                        viewId: "logs"
                        onClicked: stack.currentIndex = 2
                    }
                    SidebarItem {
                        id: btnSettings
                        icon: "⚙"
                        text: "Impostazioni"
                        viewId: "settings"
                        onClicked: stack.currentIndex = 3
                    }
                }

                Layout.fillHeight: true

                // Status pills bottom
                ColumnLayout {
                    Layout.fillWidth: true
                    spacing: 4

                    StatusPill {
                        id: pillEngine
                        label: "MOTORE"
                        variant: backend.paused ? "hold" : "buy"
                    }
                    StatusPill {
                        id: pillFeed
                        label: "FEED"
                        variant: "info"
                    }
                    StatusPill {
                        id: pillBridge
                        label: "BRIDGE EA"
                        variant: "muted"
                    }
                }
            }
        }

        // ─── CONTENUTO PRINCIPALE ───
        StackLayout {
            id: stack
            Layout.fillWidth: true
            Layout.fillHeight: true
            currentIndex: 0

            DashboardView { backend: root.backend }
            BacktestView { backend: root.backend }
            LogsView { backend: root.backend }
            SettingsView { backend: root.backend }
        }
    }

    // ─── TOAST CONTAINER ───
    ToastContainer { id: toastContainer }

    // ─── REACT TO BACKEND SIGNALS ───
    Connections {
        target: backend
        onShowToast: toastContainer.show(title, message, variant, duration)
    }
}

/**
 * Chart Panel — Grafico a candele professionale con Qt Charts
 * - Candele OHLC con EMA 8/21/50
 * - Volume in pannello inferiore
 * - Crosshair interattivo con tooltip
 * - Zoom/pan con mouse
 */
import QtQuick
import QtQuick.Controls
import QtQuick.Layouts
import QtCharts

Item {
    id: chartPanel
    property Backend backend: null

    // Toolbar
    ColumnLayout {
        anchors.fill: parent
        spacing: Theme.sp2

        // Toolbar timeframe + overlay
        ChartToolbar {
            id: toolbar
            backend: chartPanel.backend
            Layout.fillWidth: true
        }

        // Grafico + Volume
        SplitView {
            id: chartSplit
            Layout.fillWidth: true
            Layout.fillHeight: true
            orientation: Qt.Vertical
            handleDelegate: Rectangle {
                height: 8
                color: Theme.borderSecondary
                Rectangle { anchors.centerIn: parent; width: 60; height: 4; radius: 2; color: Theme.borderSecondary }
            }

            // Grafico prezzo
            ChartView {
                id: chartView
                Layout.fillWidth: true
                Layout.fillHeight: true
                Layout.minimumHeight: 280
                antialiasing: true
                theme: ChartView.ChartThemeDark
                backgroundColor: Theme.chartBg
                animationOptions: ChartView.NoAnimation
                legend.visible: false
                margins.top: 16; margins.bottom: 8; margins.left: 60; margins.right: 12

                // Serie candele
                CandlestickSeries {
                    id: candles
                    name: "Candele"
                    increasingColor: Theme.buy
                    decreasingColor: Theme.sell
                    bodyWidth: 0.7
                    capsVisible: false
                }

                // EMA lines
                LineSeries {
                    id: ema8
                    name: "EMA 8"
                    color: Theme.ema8
                    width: 2
                    useOpenGL: true
                }
                LineSeries {
                    id: ema21
                    name: "EMA 21"
                    color: Theme.ema21
                    width: 2
                    useOpenGL: true
                }
                LineSeries {
                    id: ema50
                    name: "EMA 50"
                    color: Theme.ema50
                    width: 1.5
                    style: Qt.DashLine
                    useOpenGL: true
                }

                // Assi
                ValueAxis {
                    id: axisX
                    min: 0
                    max: 500
                    visible: false
                    gridLineVisible: false
                }
                ValueAxis {
                    id: axisY
                    min: 0
                    max: 1
                    gridLineColor: Theme.chartGrid
                    gridLineVisible: true
                    minorGridLineColor: Theme.chartGridMinor
                    minorGridLineVisible: true
                    labelsColor: Theme.textSecondary
                    labelsFont: Theme.fontMono(Theme.fontXS)
                    labelFormat: "%.2f"
                    tickCount: 6
                }
                ValueAxis {
                    id: axisYRight
                    min: 0
                    max: 1
                    gridLineVisible: false
                    labelsVisible: false
                    opposite: true
                }

                // Crosshair
                Rectangle {
                    id: crosshairV
                    width: 1; color: Theme.chartCrosshair
                    visible: chartView.crosshairEnabled
                    anchors.left: chartView.mapToPosition(Qt.point(chartView.crosshairX, 0)).x
                    anchors.top: chartView.margins.top
                    anchors.bottom: chartView.height - chartView.margins.bottom
                }
                Rectangle {
                    id: crosshairH
                    height: 1; color: Theme.chartCrosshair
                    visible: chartView.crosshairEnabled
                    anchors.top: chartView.mapToPosition(Qt.point(0, chartView.crosshairY)).y
                    anchors.left: chartView.margins.left
                    anchors.right: chartView.width - chartView.margins.right
                }

                // Tooltip crosshair
                Rectangle {
                    id: tooltip
                    visible: chartView.crosshairEnabled && chartView.hoverIndex >= 0
                    radius: 4
                    color: Theme.chartTooltipBg
                    border.color: Theme.chartTooltipBorder
                    border.width: 1
                    x: Math.min(Math.max(chartView.crosshairX + 10, chartView.margins.left + 10),
                                chartView.width - width - 10)
                    y: Math.max(chartView.crosshairY - 20, chartView.margins.top + 10)
                    Layer.enabled: true
                    Layer.effect: DropShadow {
                        horizontalOffset: 0; verticalOffset: 2; radius: 8
                        color: Qt.rgba(0, 0, 0, 0.3)
                    }

                    Text {
                        id: tooltipText
                        anchors.fill: parent
                        anchors.margins: 8
                        font: Theme.fontMono(Theme.fontXS)
                        color: Theme.textPrimary
                    }
                }

                // Header prezzo corrente
                Rectangle {
                    anchors.left: parent.left; anchors.leftMargin: 70
                    anchors.top: parent.top; anchors.topMargin: 4
                    height: 20
                    color: "transparent"

                    Text {
                        id: headerText
                        anchors.left: parent.left; anchors.verticalCenter: parent.verticalCenter
                        font: Theme.fontMono(11, 700)
                    }
                }

                // Legenda EMA
                Row {
                    anchors.right: parent.right; anchors.rightMargin: 10
                    anchors.top: parent.top; anchors.topMargin: 4
                    spacing: 16

                    LegendItem { label: "EMA 8"; color: Theme.ema8; visible: toolbar.showEMA8 }
                    LegendItem { label: "EMA 21"; color: Theme.ema21; visible: toolbar.showEMA21 }
                    LegendItem { label: "EMA 50"; color: Theme.ema50; visible: toolbar.showEMA50 }
                }

                // Axis assignment
                axes: [axisX, axisY]
                series: [candles, ema8, ema21, ema50]

                // Crosshair handling
                property bool crosshairEnabled: false
                property real crosshairX: 0
                property real crosshairY: 0
                property int hoverIndex: -1
                property real candleWidth: 0

                // Update functions (chiamate da backend)
                function updateCandles(o, h, l, c, vol) {
                    // Viene chiamato dal backend con nuovi dati
                    // Qui si appende alla serie esistente
                    if (candles.count >= 500) {
                        candles.remove(0)
                        ema8.remove(0)
                        ema21.remove(0)
                        ema50.remove(0)
                    }
                    var idx = candles.count
                    candles.append(idx, h, l, o, c)
                    // EMA verranno aggiornate dal backend separatamente
                }

                function updateEMA(period, values) {
                    var series = period === 8 ? ema8 : (period === 21 ? ema21 : ema50)
                    series.clear()
                    for (var i = 0; i < values.length; i++) {
                        series.append(i, values[i])
                    }
                }

                function setCrosshair(x, y) {
                    crosshairX = x
                    crosshairY = y
                    crosshairEnabled = true
                    updateTooltip()
                }

                function clearCrosshair() {
                    crosshairEnabled = false
                }

                function updateTooltip() {
                    if (hoverIndex >= 0 && hoverIndex < candles.count) {
                        var c = candles.at(hoverIndex)
                        tooltipText.text = "O:" + c.open.toFixed(2) + " H:" + c.high.toFixed(2) +
                                           " L:" + c.low.toFixed(2) + " C:" + c.close.toFixed(2)
                        tooltip.width = tooltipText.implicitWidth + 20
                        tooltip.height = tooltipText.implicitHeight + 12
                    }
                }
            }

            // Volume panel
            ChartView {
                id: volumeView
                Layout.fillWidth: true
                Layout.preferredHeight: 120
                Layout.maximumHeight: 200
                antialiasing: true
                theme: ChartView.ChartThemeDark
                backgroundColor: Theme.chartBg
                animationOptions: ChartView.NoAnimation
                legend.visible: false
                margins.top: 4; margins.bottom: 8; margins.left: 60; margins.right: 12

                BarSeries {
                    id: volumeSeries
                    barWidth: 0.7
                }

                ValueAxis {
                    id: volAxisX
                    min: 0; max: 500; visible: false; gridLineVisible: false
                }
                ValueAxis {
                    id: volAxisY
                    min: 0; max: 1
                    gridLineColor: Theme.chartGridMinor
                    labelsColor: Theme.textMuted
                    labelsFont: Theme.fontMono(9)
                    tickCount: 3
                }

                axes: [volAxisX, volAxisY]
                series: [volumeSeries]

                // Sync X axis with main chart
                property alias viewMin: volAxisX.min
                property alias viewMax: volAxisX.max
            }

            // Sync X axes
            Binding { target: volAxisX; property: "min"; value: axisX.min }
            Binding { target: volAxisX; property: "max"; value: axisX.max }
        }
    }

    // ─── FUNZIONI AGGIORNAMENTO ───
    function updateCandles(o, h, l, c, vol) {
        chartView.updateCandles(o, h, l, c, vol)
    }

    function updateEMA(period, values) {
        chartView.updateEMA(period, values)
    }
}

// ═══════════════════════════════════════════════════════════════════
// Chart Toolbar — Timeframe + Overlay toggles
// ═══════════════════════════════════════════════════════════════════
Item {
    id: ChartToolbar
    property Backend backend: null
    property bool showEMA8: true
    property bool showEMA21: true
    property bool showEMA50: true
    property bool showVolume: true
    property bool showGrid: true

    Layout.fillWidth: true
    Layout.preferredHeight: 48
    Layout.maximumHeight: 48

    // Scroll orizzontale per evitare troncamento
    Flickable {
        id: toolbarScroll
        anchors.fill: parent
        contentWidth: toolbarContent.implicitWidth
        clip: true
        horizontalVelocity: 0
        boundsBehavior: Flickable.StopAtBounds

        Row {
            id: toolbarContent
            spacing: Theme.sp2
            Layout.alignment: Qt.AlignLeft | Qt.AlignVCenter

            // Timeframe buttons (esclusivi)
            Repeater {
                model: ["M1", "M5", "M15", "H1", "H4"]
                TFButton {
                    text: modelData
                    checked: modelData === "M1"
                    onClicked: {
                        for (var i = 0; i < toolbarContent.children.length; i++) {
                            var btn = toolbarContent.children[i]
                            if (btn.objectName === "tfButton") btn.checked = (btn === this)
                        }
                        // backend.setTimeframe(modelData) // TODO: implementare
                    }
                }
            }

            Separator { orientation: Qt.Vertical; color: Theme.borderSecondary; Layout.preferredHeight: 30 }

            // Overlay toggles
            ToggleButton {
                text: "EMA 8"
                checked: showEMA8
                onToggled: showEMA8 = checked
            }
            ToggleButton {
                text: "EMA 21"
                checked: showEMA21
                onToggled: showEMA21 = checked
            }
            ToggleButton {
                text: "EMA 50"
                checked: showEMA50
                onToggled: showEMA50 = checked
            }
            ToggleButton {
                text: "Volume"
                checked: showVolume
                onToggled: showVolume = checked
            }

            Separator { orientation: Qt.Vertical; color: Theme.borderSecondary; Layout.preferredHeight: 30 }

            ToggleButton {
                text: "Grid"
                checked: showGrid
                onToggled: showGrid = checked
            }

            Button {
                text: "Reset View"
                onClicked: {
                    // chartView.resetView() // TODO
                }
            }
        }
    }
}

// ═══════════════════════════════════════════════════════════════════
// Toolbar Button — Timeframe (esclusivo)
// ═══════════════════════════════════════════════════════════════════
Button {
    id: TFButton
    objectName: "tfButton"
    property bool checked: false
    checkable: true
    Layout.preferredHeight: 30
    Layout.minimumWidth: fontMetrics.horizontalAdvance(text) + 22

    background: Rectangle {
        radius: Theme.radiusSM
        color: checked ? Qt.rgba(43, 107, 255, 0.24) : Theme.bgElevated
        border.color: checked ? Theme.info : Theme.borderSecondary
        border.width: 1
    }
    contentItem: Text {
        text: parent.text
        font: Theme.fontMono(Theme.fontSM, 700)
        color: checked ? Theme.textPrimary : Theme.textSecondary
        horizontalAlignment: Text.AlignHCenter
        verticalAlignment: Text.AlignVCenter
    }
}

// ═══════════════════════════════════════════════════════════════════
// Toggle Button — Overlay
// ═══════════════════════════════════════════════════════════════════
Button {
    id: ToggleButton
    checkable: true
    Layout.preferredHeight: 30
    Layout.minimumWidth: fontMetrics.horizontalAdvance(text) + 22

    background: Rectangle {
        radius: Theme.radiusSM
        color: checked ? Qt.rgba(43, 107, 255, 0.24) : Theme.bgElevated
        border.color: checked ? Theme.info : Theme.borderSecondary
        border.width: 1
    }
    contentItem: Text {
        text: parent.text
        font: Theme.fontUI(Theme.fontSM, 600)
        color: checked ? Theme.textPrimary : Theme.textSecondary
    }
}

// ═══════════════════════════════════════════════════════════════════
// Legend Item
// ═══════════════════════════════════════════════════════════════════
Item {
    id: LegendItem
    property string label: ""
    property color color: Theme.textMuted
    property bool visible: true

    Row {
        visible: parent.visible
        spacing: 4
        Rectangle { width: 16; height: 3; color: parent.color; radius: 1.5 }
        Text { text: label; font: Theme.fontUI(Theme.fontXS); color: Theme.textSecondary }
    }
}

// ═══════════════════════════════════════════════════════════════════
// Separator
// ═══════════════════════════════════════════════════════════════════
Rectangle {
    id: Separator
    property Qt.Orientation orientation: Qt.Vertical
    property color color: Theme.borderSecondary
    color: parent.color
    width: orientation === Qt.Vertical ? 1 : 0
    height: orientation === Qt.Horizontal ? 1 : 0
    Layout.preferredWidth: orientation === Qt.Vertical ? 1 : 0
    Layout.preferredHeight: orientation === Qt.Horizontal ? 1 : 0
}

/**
 * Dashboard View — Vista Live Dashboard
 * Split: Chart (65%) | Pannello Decisione + Metriche + Filtri + Bridge (35%)
 */
import QtQuick
import QtQuick.Controls
import QtQuick.Layouts
import QtCharts
import JarvisBackend 1.0
import "components"

Item {
    id: dash
    property Backend backend: Backend {}

    Connections {
        target: backend
        onPriceUpdate: chartView.updateCandles(o, h, l, c, vol)
        onSignalUpdate: decisionPanel.updateSignal(action, conf, sl, tp, reason)
        onEquityUpdate: metrics.updateEquity(equity, dayPnl, weekPnl)
        onLogUpdate: logsPanel.append(level, msg)
    }

    Rectangle {
        anchors.fill: parent
        color: "transparent"

        SplitView {
            anchors.fill: parent
            orientation: Qt.Horizontal
            handleDelegate: Rectangle {
                width: 10
                color: Theme.borderSecondary
                hoverEnabled: true
                Rectangle {
                    anchors.centerIn: parent
                    width: 4; height: 60
                    radius: 2
                    color: Theme.borderSecondary
                }
            }

            // ─── LATO SINISTRO: GRAFICO ───
            ChartPanel {
                id: chartPanel
                Layout.fillWidth: true
                Layout.fillHeight: true
                Layout.minimumWidth: 600
                backend: dash.backend
            }

            // ─── LATO DESTRO: DECISIONE + METRICHE + FILTRI + BRIDGE ───
            ColumnLayout {
                Layout.preferredWidth: 450
                Layout.minimumWidth: 380
                Layout.maximumWidth: 520
                Layout.fillHeight: true
                spacing: Theme.sp3

                // Decision Panel (sempre visibile)
                DecisionPanel {
                    id: decisionPanel
                    backend: dash.backend
                    Layout.fillWidth: true
                    Layout.preferredHeight: 220
                }

                // Pannelli collassabili
                CollapsiblePanel {
                    title: "Metriche"
                    expanded: true
                    Layout.fillWidth: true
                    MetricsView { backend: dash.backend }
                }

                CollapsiblePanel {
                    title: "Filtri d'ingresso"
                    expanded: true
                    Layout.fillWidth: true
                    FiltersView { backend: dash.backend }
                }

                CollapsiblePanel {
                    title: "Ponte EA"
                    expanded: false
                    Layout.fillWidth: true
                    BridgeView { backend: dash.backend }
                }
            }
        }
    }
}

