Index: JARVIS_v20/frontend/nginx.conf
===================================================================
--- JARVIS_v20/frontend/nginx.conf	
+++ JARVIS_v20/frontend/nginx.conf	
@@ -0,0 +1,61 @@
+server {
+    listen 3000;
+    server_name localhost;
+    root /usr/share/nginx/html;
+    index index.html;
+
+    # Gzip compression
+    gzip on;
+    gzip_vary on;
+    gzip_min_length 1024;
+    gzip_types text/plain text/css text/xml text/javascript application/javascript application/xml+rss application/json;
+
+    # Security headers
+    add_header X-Frame-Options "SAMEORIGIN";
+    add_header X-Content-Type-Options "nosniff";
+    add_header X-XSS-Protection "1; mode=block";
+
+    # Static assets caching
+    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2)$ {
+        expires 1y;
+        add_header Cache-Control "public, immutable";
+    }
+
+    # SPA routing - fallback to index.html
+    location / {
+        try_files $uri $uri/ /index.html;
+    }
+
+    # API proxy
+    location /api/ {
+        proxy_pass http://jarvis-core:8000;
+        proxy_http_version 1.1;
+        proxy_set_header Upgrade $http_upgrade;
+        proxy_set_header Connection 'upgrade';
+        proxy_set_header Host $host;
+        proxy_set_header X-Real-IP $remote_addr;
+        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
+        proxy_set_header X-Forwarded-Proto $scheme;
+        proxy_cache_bypass $http_upgrade;
+        proxy_read_timeout 300s;
+    }
+
+    # WebSocket proxy
+    location /ws {
+        proxy_pass http://jarvis-core:8000;
+        proxy_http_version 1.1;
+        proxy_set_header Upgrade $http_upgrade;
+        proxy_set_header Connection "upgrade";
+        proxy_set_header Host $host;
+        proxy_set_header X-Real-IP $remote_addr;
+        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
+        proxy_set_header X-Forwarded-Proto $scheme;
+        proxy_read_timeout 86400;
+    }
+
+    # Health check
+    location /healthz {
+        proxy_pass http://jarvis-core:8000/healthz;
+        access_log off;
+    }
+}
\ No newline at end of file

Index: JARVIS_v20/frontend/src/index.css
===================================================================
--- JARVIS_v20/frontend/src/index.css	
+++ JARVIS_v20/frontend/src/index.css	
@@ -0,0 +1,138 @@
+@tailwind base;
+@tailwind components;
+@tailwind utilities;
+
+@layer base {
+  :root {
+    --color-bg: #0a0e17;
+    --color-surface: #111827;
+    --color-elevated: #1f2937;
+    --color-border: #374151;
+    --color-primary: #2b6bff;
+    --color-success: #10b981;
+    --color-warning: #f59e0b;
+    --color-danger: #ef4444;
+  }
+
+  * {
+    @apply border-jarvis-border;
+  }
+
+  body {
+    @apply bg-jarvis-bg text-jarvis-text font-sans antialiased;
+  }
+
+  ::-webkit-scrollbar {
+    width: 8px;
+    height: 8px;
+  }
+
+  ::-webkit-scrollbar-track {
+    @apply bg-jarvis-bg;
+  }
+
+  ::-webkit-scrollbar-thumb {
+    @apply bg-jarvis-border rounded-full;
+  }
+
+  ::-webkit-scrollbar-thumb:hover {
+    @apply bg-jarvis-textMuted;
+  }
+}
+
+@layer components {
+  .btn {
+    @apply inline-flex items-center justify-center gap-2 px-4 py-2 rounded-lg font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-jarvis-bg disabled:opacity-50 disabled:cursor-not-allowed;
+  }
+
+  .btn-primary {
+    @apply btn bg-jarvis-primary text-white hover:bg-blue-600 focus:ring-jarvis-primary;
+  }
+
+  .btn-secondary {
+    @apply btn bg-jarvis-elevated text-jarvis-text hover:bg-jarvis-border focus:ring-jarvis-border;
+  }
+
+  .btn-danger {
+    @apply btn bg-jarvis-danger text-white hover:bg-red-600 focus:ring-jarvis-danger;
+  }
+
+  .btn-ghost {
+    @apply btn bg-transparent hover:bg-jarvis-elevated focus:ring-jarvis-border;
+  }
+
+  .input {
