    tailwindcss: {},
    autoprefixer: {},
  },
}

import React from 'react'
import ReactDOM from 'react-dom/client'
import { BrowserRouter } from 'react-router-dom'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { Toaster } from 'react-hot-toast'
import App from './App'
import './index.css'

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchInterval: 5000,
      staleTime: 3000,
      retry: 1,
    },
  },
})

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <BrowserRouter>
        <App />
        <Toaster
          position="top-right"
          toastOptions={{
            duration: 4000,
            style: {
              background: '#111827',
              color: '#f9fafb',
              border: '1px solid #374151',
            },
            success: { iconTheme: { primary: '#10b981', secondary: '#f9fafb' } },
            error: { iconTheme: { primary: '#ef4444', secondary: '#f9fafb' } },
          }}
        />
      </BrowserRouter>
    </QueryClientProvider>
  </React.StrictMode>
)

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --color-bg: #0a0e17;
    --color-surface: #111827;
    --color-elevated: #1f2937;
    --color-border: #374151;
    --color-primary: #2b6bff;
    --color-success: #10b981;
    --color-warning: #f59e0b;
    --color-danger: #ef4444;
  }

  * {
    @apply border-jarvis-border;
  }

  body {
    @apply bg-jarvis-bg text-jarvis-text font-sans antialiased;
  }

  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }

  ::-webkit-scrollbar-track {
    @apply bg-jarvis-bg;
  }

  ::-webkit-scrollbar-thumb {
    @apply bg-jarvis-border rounded-full;
  }

  ::-webkit-scrollbar-thumb:hover {
    @apply bg-jarvis-textMuted;
  }
}

@layer components {
  .btn {
    @apply inline-flex items-center justify-center gap-2 px-4 py-2 rounded-lg font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-jarvis-bg disabled:opacity-50 disabled:cursor-not-allowed;
  }

  .btn-primary {
    @apply btn bg-jarvis-primary text-white hover:bg-blue-600 focus:ring-jarvis-primary;
  }

  .btn-secondary {
    @apply btn bg-jarvis-elevated text-jarvis-text hover:bg-jarvis-border focus:ring-jarvis-border;
  }

  .btn-danger {
    @apply btn bg-jarvis-danger text-white hover:bg-red-600 focus:ring-jarvis-danger;
  }

  .btn-ghost {
    @apply btn bg-transparent hover:bg-jarvis-elevated focus:ring-jarvis-border;
  }

  .input {
    @apply w-full px-3 py-2 bg-jarvis-bg border-jarvis-border rounded-lg text-jarvis-text placeholder-jarvis-textMuted focus:outline-none focus:ring-2 focus:ring-jarvis-primary focus:border-transparent transition-all;
  }

  .label {
    @apply block text-sm font-medium text-jarvis-textSecondary mb-1;
  }

  .card {
    @apply bg-jarvis-surface border border-jarvis-border rounded-xl p-6;
  }

  .panel {
    @apply bg-jarvis-elevated border border-jarvis-border rounded-lg p-4;
  }

  .badge {
    @apply inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium;
  }

  .badge-success {
    @apply badge bg-green-500/20 text-green-400;
  }

  .badge-warning {
    @apply badge bg-yellow-500/20 text-yellow-400;
  }

  .badge-danger {
    @apply badge bg-red-500/20 text-red-400;
  }

  .badge-info {
    @apply badge bg-blue-500/20 text-blue-400;
  }

  .stat-card {
    @apply card flex flex-col gap-2;
  }

  .stat-value {
    @apply text-3xl font-bold font-mono text-jarvis-text;
  }

  .stat-label {
    @apply text-sm text-jarvis-textMuted uppercase tracking-wide;
  }

  .stat-delta {
    @apply text-sm font-medium;
  }

  .stat-delta-positive {
    @apply stat-delta text-green-400;
  }

  .stat-delta-negative {
    @apply stat-delta text-red-400;
  }
}

@layer utilities {
  .text-balance {
    text-wrap: balance;
