import { create } from 'zustand'
import { persist } from 'zustand/middleware'

interface AuthState {
  token: string | null
  user: { username: string; scopes: string[] } | null
  isAuthenticated: boolean
  login: (username: string, password: string) => Promise<void>
  logout: () => void
  checkAuth: () => Promise<void>
}

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000'

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      token: null,
      user: null,
      isAuthenticated: false,

      login: async (username: string, password: string) => {
        const res = await fetch(`${API_URL}/auth/token`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: new URLSearchParams({ username, password }),
        })

        if (!res.ok) {
          const err = await res.json()
          throw new Error(err.detail || 'Login failed')
        }

        const data = await res.json()
        set({ token: data.access_token, isAuthenticated: true })
      },

      logout: () => {
        set({ token: null, user: null, isAuthenticated: false })
      },

      checkAuth: async () => {
        const token = get().token
        if (!token) return

        try {
          const res = await fetch(`${API_URL}/auth/me`, {
            headers: { Authorization: `Bearer ${token}` },
          })

          if (res.ok) {
            const user = await res.json()
            set({ user, isAuthenticated: true })
          } else {
            get().logout()
          }
        } catch {
          get().logout()
        }
      },
    }),
    {
      name: 'jarvis-auth',
      partialize: (state) => ({ token: state.token }),
    }
  )
)

import { create } from 'zustand'
import { Decision, Quote, Equity } from '@/types'

interface EngineState {
  // Connection
  ws: WebSocket | null
  connected: boolean
  connecting: boolean
  error: string | null

  // Engine status
  running: boolean
  paused: boolean
  symbol: string
  testMode: boolean
  tickCount: number
  errorCount: number

  // Market data
  quote: Quote | null
  candles: Map<string, any[]> // timeframe -> candles

  // Decisions
  latestDecision: Decision | null
  decisionHistory: Decision[]

  // Equity & Risk
  equity: Equity | null
  riskSnapshot: any
  riskEngineStatus: any

  // Health
  health: any

  // Actions
  connect: () => void
  disconnect: () => void
  subscribe: (channels: string[]) => void
  unsubscribe: (channels: string[]) => void
  sendCommand: (command: string, params?: any) => void

  // Engine controls
  startEngine: (config: any) => Promise<void>
  stopEngine: () => Promise<void>
  pauseEngine: (pause: boolean) => Promise<void>
  switchSymbol: (symbol: string) => Promise<void>
}

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000'
const WS_URL = import.meta.env.VITE_WS_URL || 'ws://localhost:8000'

export const useEngineStore = create<EngineState>((set, get) => ({
  // Initial state
  ws: null,
  connected: false,
  connecting: false,
  error: null,

  running: false,
  paused: true,
  symbol: 'XAUUSD',
  testMode: true,
  tickCount: 0,
  errorCount: 0,

  quote: null,
  candles: new Map(),

  latestDecision: null,
  decisionHistory: [],

  equity: null,
  riskSnapshot: {},
  riskEngineStatus: {},

  health: { overall: 'unknown', checks: {} },

  // WebSocket connection
  connect: () => {
    const { ws, connecting, connected } = get()
    if (ws || connecting || connected) return

    set({ connecting: true, error: null })

    const token = useAuthStore.getState().token
    const wsUrl = `${WS_URL}/ws${token ? `?token=${token}` : ''}`

    const websocket = new WebSocket(wsUrl)

    websocket.onopen = () => {
      set({ ws: websocket, connected: true, connecting: false, error: null })

      // Subscribe to channels
      get().subscribe(['decisions', 'equity', 'quotes', 'logs', 'errors', 'health'])

      // Request initial status
      websocket.send(JSON.stringify({ type: 'command', command: 'get_status' }))
    }

    websocket.onmessage = (event) => {
      try {
        const msg = JSON.parse(event.data)
        handleMessage(msg)
      } catch (e) {
        console.error('WS parse error:', e)
      }
    }

    websocket.onclose = () => {
      set({ ws: null, connected: false, connecting: false })
      // Auto-reconnect after 5s
      setTimeout(() => get().connect(), 5000)
    }

    websocket.onerror = (err) => {
      set({ error: 'WebSocket error', connecting: false })
      console.error('WS error:', err)
    }

    function handleMessage(msg: any) {
      const { channel, data } = msg

      switch (channel) {
        case 'decisions':
          set((state) => ({
            latestDecision: data,
            decisionHistory: [data, ...state.decisionHistory.slice(0, 99)],
          }))
          break

        case 'equity':
          set({ equity: data })
          break

        case 'quotes':
          set({ quote: data })
          break

        case 'health':
          set({ health: data })
          break

        case 'init':
          set({
            running: data.engine_status?.running ?? false,
            paused: data.engine_status?.paused ?? true,
            symbol: data.engine_status?.symbol ?? 'XAUUSD',
          })
          break
      }
    }
  },

  disconnect: () => {
    const { ws } = get()
    if (ws) {
      ws.close()
      set({ ws: null, connected: false })
    }
  },

  subscribe: (channels: string[]) => {
    const { ws } = get()
    if (ws?.readyState === WebSocket.OPEN) {
      channels.forEach(ch => ws.send(JSON.stringify({ type: 'subscribe', channel: ch })))
    }
  },

  unsubscribe: (channels: string[]) => {
    const { ws } = get()
    if (ws?.readyState === WebSocket.OPEN) {
      channels.forEach(ch => ws.send(JSON.stringify({ type: 'unsubscribe', channel: ch })))
    }
  },

  sendCommand: (command: string, params: any = {}) => {
    const { ws } = get()
    if (ws?.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: 'command', command, params }))
    }
  },

  // Engine REST controls
  startEngine: async (config: any) => {
    const token = useAuthStore.getState().token
    const res = await fetch(`${API_URL}/engine/start`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(config),
    })

    if (!res.ok) throw new Error('Failed to start engine')

    set({ running: true, ...config })
  },

  stopEngine: async () => {
    const token = useAuthStore.getState().token
    await fetch(`${API_URL}/engine/stop`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
    })
    set({ running: false })
  },

  pauseEngine: async (pause: boolean) => {
    const token = useAuthStore.getState().token
    await fetch(`${API_URL}/engine/pause`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ pause }),
    })
    set({ paused: pause })
  },

  switchSymbol: async (symbol: string) => {
    const token = useAuthStore.getState().token
    await fetch(`${API_URL}/engine/switch_symbol`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ symbol }),
    })
    set({ symbol })
  },
}))

// Import auth store for token access
import { useAuthStore } from './authStore'

import { useAuthStore } from '@/store/authStore'

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000'

class ApiClient {
  private getHeaders(): HeadersInit {
    const token = useAuthStore.getState().token
    return {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    }
  }

  async request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
    const res = await fetch(`${API_URL}${endpoint}`, {
      ...options,
      headers: {
        ...this.getHeaders(),
        ...options.headers,
      },
    })

    if (!res.ok) {
      const err = await res.json().catch(() => ({ detail: res.statusText }))
      throw new Error(err.detail || `HTTP ${res.status}`)
    }

    if (res.status === 204) return {} as T
    return res.json()
  }

  // Auth
  login(username: string, password: string) {
    return this.request<{ access_token: string; token_type: string }>('/auth/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ username, password }),
    })
  }

  getMe() {
    return this.request<{ username: string; scopes: string[] }>('/auth/me')
  }

  // Engine
  getEngineStatus() {
    return this.request<any>('/engine/status')
  }

  startEngine(config: any) {
    return this.request<any>('/engine/start', {
      method: 'POST',
      body: JSON.stringify(config),
    })
  }

  stopEngine() {
    return this.request<any>('/engine/stop', { method: 'POST' })
  }

  pauseEngine(pause: boolean) {
    return this.request<any>('/engine/pause', {
      method: 'POST',
      body: JSON.stringify({ pause }),
    })
  }

  switchSymbol(symbol: string) {
    return this.request<any>('/engine/switch_symbol', {
      method: 'POST',
      body: JSON.stringify({ symbol }),
    })
  }

  // Market data
  getQuote(symbol?: string) {
    return this.request<any>(`/market/quote${symbol ? `?symbol=${symbol}` : ''}`)
  }

  getCandles(symbol: string, timeframe: string = 'M1', count: number = 500) {
    return this.request<any>(`/market/candles?symbol=${symbol}&timeframe=${timeframe}&count=${count}`)
  }

  // Decisions
  getLatestDecision() {
    return this.request<any>('/decisions/latest')
  }

  getDecisionHistory(limit: number = 100) {
    return this.request<any>(`/decisions/history?limit=${limit}`)
  }

  // Equity & Risk
  getEquity() {
    return this.request<any>('/equity')
  }

  getRiskSnapshot() {
    return this.request<any>('/risk/snapshot')
  }

  getRiskEngineStatus() {
    return this.request<any>('/risk/engine_status')
  }

  resetCooldown() {
    return this.request<any>('/risk/reset_cooldown', { method: 'POST' })
  }

  resetDay() {
    return this.request<any>('/risk/reset_day', { method: 'POST' })
  }

  // Backtest
  runBacktest(config: any) {
    return this.request<any>('/backtest/run', {
      method: 'POST',
      body: JSON.stringify(config),
    })
  }

  getBacktestStatus(taskId: string) {
    return this.request<any>(`/backtest/status/${taskId}`)
  }

  getBacktestReport(taskId: string) {
    return fetch(`${API_URL}/backtest/report/${taskId}`, {
      headers: this.getHeaders(),
    })
  }

  listBacktests() {
    return this.request<any>('/backtest/list')
  }

  // Optimization
  runOptimization(config: any) {
    return this.request<any>('/optimize/run', {
      method: 'POST',
      body: JSON.stringify(config),
    })
  }

  // Config
  getConfig() {
    return this.request<any>('/config')
  }

  updateConfig(params: Record<string, any>, backup = true) {
    return this.request<any>('/config/update', {
      method: 'POST',
      body: JSON.stringify({ params, backup }),
    })
  }

  // Health
  getHealth() {
    return this.request<any>('/health')
  }

  forceHealthCheck() {
    return this.request<any>('/health/force_check', { method: 'POST' })
  }

  resumeFromCircuitBreaker() {
    return this.request<any>('/health/resume', { method: 'POST' })
  }

  // Logs
  getLogs(level: string = 'INFO', limit: number = 100) {
    return this.request<any>(`/logs?level=${level}&limit=${limit}`)
  }
}

export const api = new ApiClient()

