export function useStartEngine() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (config: any) => api.startEngine(config),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['engineStatus'] })
    },
  })
}

export function useStopEngine() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: () => api.stopEngine(),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['engineStatus'] })
    },
  })
}

export function usePauseEngine() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (pause: boolean) => api.pauseEngine(pause),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['engineStatus'] })
    },
  })
}

export function useRunBacktest() {
  return useMutation({
    mutationFn: (config: any) => api.runBacktest(config),
  })
}

export function useBacktestStatus(taskId: string) {
  return useQuery({
    queryKey: ['backtestStatus', taskId],
    queryFn: () => api.getBacktestStatus(taskId),
    refetchInterval: (data) => data?.status === 'running' ? 2000 : false,
    enabled: !!taskId,
  })
}

