  const ema8Ref = useRef<ISeriesApi<'Line'> | null>(null)
  const ema21Ref = useRef<ISeriesApi<'Line'> | null>(null)
  const ema50Ref = useRef<ISeriesApi<'Line'> | null>(null)

  // Initialize chart
  useEffect(() => {
    if (!containerRef.current) return

    const chart = createChart(containerRef.current, {
      layout: {
        background: { type: 'solid', color: '#0a0e17' },
        textColor: '#9ca3af',
        fontSize: 11,
        fontFamily: 'JetBrains Mono, monospace',
      },
      grid: {
        vertLines: { color: '#1f2937' },
        horzLines: { color: '#1f2937' },
      },
      crosshair: {
        mode: 1, // Normal
        vertLine: { color: '#374151', width: 1, style: 2, labelBackgroundColor: '#1f2937' },
        horzLine: { color: '#374151', width: 1, style: 2, labelBackgroundColor: '#1f2937' },
      },
      rightPriceScale: {
        borderColor: '#374151',
        scaleMargins: { top: 0.1, bottom: showVolume ? 0.35 : 0.1 },
      },
      timeScale: {
        borderColor: '#374151',
        timeVisible: true,
        secondsVisible: false,
        tickMarkFormatter: (time: Time, tickMarkType: string, locale: string) => {
          const date = new Date((time as number) * 1000)
          if (tickMarkType === 'year') return date.toLocaleDateString(locale, { year: 'numeric' })
          if (tickMarkType === 'month') return date.toLocaleDateString(locale, { month: 'short' })
          if (tickMarkType === 'dayOfMonth') return date.toLocaleDateString(locale, { day: 'numeric', month: 'short' })
          return date.toLocaleTimeString(locale, { hour: '2-digit', minute: '2-digit' })
        },
      },
      handleScroll: { mouseWheel: true, pressedMouseMove: true, horzTouchDrag: true, vertTouchDrag: true },
      handleScale: { axisPressedMouseMove: true, mouseWheel: true, pinch: true },
      localization: { locale: 'it-IT', dateFormat: 'dd/MM/yyyy' },
    })

    chartRef.current = chart

    // Candle series
    const candleSeries = chart.addCandlestickSeries({
      upColor: '#10b981',
      downColor: '#ef4444',
      borderUpColor: '#10b981',
      borderDownColor: '#ef4444',
      wickUpColor: '#10b981',
      wickDownColor: '#ef4444',
      priceFormat: { type: 'price', precision: 2, minMove: 0.01 },
    })
    candleSeriesRef.current = candleSeries

    // EMA series
    if (showEMA8) {
      const ema8 = chart.addLineSeries({
        color: '#2b6bff',
        lineWidth: 1.5,
        priceLineVisible: false,
        lastValueVisible: true,
        title: 'EMA 8',
      })
      ema8Ref.current = ema8
    }

    if (showEMA21) {
      const ema21 = chart.addLineSeries({
        color: '#f59e0b',
        lineWidth: 1.5,
        priceLineVisible: false,
        lastValueVisible: true,
        title: 'EMA 21',
      })
      ema21Ref.current = ema21
    }

    if (showEMA50) {
      const ema50 = chart.addLineSeries({
        color: '#8b5cf6',
        lineWidth: 1,
        lineStyle: 2, // Dashed
        priceLineVisible: false,
        lastValueVisible: true,
        title: 'EMA 50',
      })
      ema50Ref.current = ema50
    }

    // Volume series (separate pane)
    if (showVolume) {
      const volumeSeries = chart.addHistogramSeries({
        color: '#6b7280',
        priceFormat: { type: 'volume' },
        priceScaleId: 'volume',
        base: 0,
      })
      volumeSeriesRef.current = volumeSeries

      chart.applyOptions({
        layout: { background: { type: 'solid', color: '#0a0e17' } },
      })

      // Create volume pane
      const volumePane = chart.addHistogramSeries({
        color: '#6b7280',
        priceFormat: { type: 'volume' },
        priceScaleId: 'volume',
        base: 0,
      })
      // Actually use the same series, just configure price scale
      chart.priceScale('volume').applyOptions({
        scaleMargins: { top: 0.7, bottom: 0 },
        borderVisible: false,
        borderColor: '#374151',
      })
    }

    // Decision markers
    if (decision && decision.action !== 'HOLD') {
      const markerTime = Math.floor(new Date(decision.ts).getTime() / 1000)
      const price = decision.action === 'BUY' 
        ? (decision.sl || quote?.bid || 0) 
        : (decision.sl || quote?.ask || 0)

      candleSeries.setMarkers([
        {
          time: markerTime,
          position: decision.action === 'BUY' ? 'belowBar' : 'aboveBar',
          color: decision.action === 'BUY' ? '#10b981' : '#ef4444',
          shape: decision.action === 'BUY' ? 'arrowUp' : 'arrowDown',
          text: `${decision.action} @${decision.confidence.toFixed(0)}%`,
        }
      ])
    }

    // Resize handler
    const resizeObserver = new ResizeObserver(() => {
      chart.resize(containerRef.current!.clientWidth, height)
    })
    resizeObserver.observe(containerRef.current)

    return () => {
      resizeObserver.disconnect()
      chart.remove()
    }
  }, [])

  // Update candle data
  useEffect(() => {
    if (!candleSeriesRef.current || candles.length === 0) return

    const data = candles.map(c => ({
      time: c.time as Time,
      open: c.open,
      high: c.high,
      low: c.low,
      close: c.close,
    }))

    candleSeriesRef.current.setData(data)
  }, [candles])

  // Update volume
  useEffect(() => {
    if (!volumeSeriesRef.current || !volume || volume.length === 0) return

    const data = volume.map((v, i) => ({
      time: candles[i]?.time as Time,
      value: v,
      color: candles[i] && candles[i].close >= candles[i].open ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)',
    }))

    volumeSeriesRef.current.setData(data)
  }, [volume, candles])

  // Update EMAs
  useEffect(() => {
    if (!emas) return

    if (ema8Ref.current && emas.ema8 && showEMA8) {
      const data = emas.ema8.map((v, i) => ({
        time: candles[i]?.time as Time,
        value: v,
      })).filter(d => !isNaN(d.value))
      ema8Ref.current.setData(data)
    }

    if (ema21Ref.current && emas.ema21 && showEMA21) {
      const data = emas.ema21.map((v, i) => ({
        time: candles[i]?.time as Time,
        value: v,
      })).filter(d => !isNaN(d.value))
      ema21Ref.current.setData(data)
    }

    if (ema50Ref.current && emas.ema50 && showEMA50) {
      const data = emas.ema50.map((v, i) => ({
        time: candles[i]?.time as Time,
        value: v,
      })).filter(d => !isNaN(d.value))
      ema50Ref.current.setData(data)
    }
  }, [emas, candles, showEMA8, showEMA21, showEMA50])

  // Update quote price line
  useEffect(() => {
    if (!chartRef.current || !quote) return

    // Update last price marker
    chartRef.current.priceScale('').applyOptions({
      // Could add price line here
    })
  }, [quote])

  return (
    <div ref={containerRef} className={clsx('w-full', className)} style={{ height }}>
      {/* Toolbar */}
      <div className="flex items-center gap-2 mb-2">
        <div className="flex items-center gap-1 bg-jarvis-elevated rounded-lg p-1 border border-jarvis-border">
          {TIMEFRAMES.map(tf => (
            <button
              key={tf}
              onClick={() => onTimeframeChange?.(tf)}
              className={clsx(
                'px-2 py-1 text-xs font-medium rounded transition-colors',
                timeframe === tf
                  ? 'bg-jarvis-primary text-white'
                  : 'text-jarvis-textSecondary hover:text-jarvis-text'
              )}
            >
              {tf}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-1 ml-auto">
          <label className="flex items-center gap-1.5 text-xs text-jarvis-textSecondary cursor-pointer">
            <input
              type="checkbox"
              checked={showEMA8}
              onChange={e => { /* TODO: update state */ }}
              className="w-4 h-4 accent-jarvis-primary"
            />
            <span style={{ color: '#2b6bff' }}>EMA 8</span>
          </label>
          <label className="flex items-center gap-1.5 text-xs text-jarvis-textSecondary cursor-pointer">
            <input
              type="checkbox"
              checked={showEMA21}
              onChange={e => { /* TODO: update state */ }}
              className="w-4 h-4 accent-jarvis-warning"
            />
            <span style={{ color: '#f59e0b' }}>EMA 21</span>
          </label>
          <label className="flex items-center gap-1.5 text-xs text-jarvis-textSecondary cursor-pointer">
            <input
              type="checkbox"
              checked={showEMA50}
              onChange={e => { /* TODO: update state */ }}
              className="w-4 h-4 accent-purple-500"
            />
            <span style={{ color: '#8b5cf6' }}>EMA 50</span>
          </label>
          <label className="flex items-center gap-1.5 text-xs text-jarvis-textSecondary cursor-pointer">
            <input
              type="checkbox"
              checked={showVolume}
              onChange={e => { /* TODO: update state */ }}
              className="w-4 h-4 accent-jarvis-textMuted"
            />
            <span>Vol</span>
          </label>
        </div>
      </div>

      {/* Current Price */}
      {quote && (
        <div className="absolute top-4 left-4 z-10 flex items-center gap-2 bg-jarvis-bg/90 backdrop-blur px-3 py-1 rounded-lg border border-jarvis-border">
          <span className="text-xs text-jarvis-textMuted">{symbol}</span>
          <span className="font-mono text-lg font-bold text-jarvis-text">{quote.bid.toFixed(2)}</span>
          <span className="text-xs text-jarvis-textMuted">/</span>
          <span className="font-mono text-lg font-bold text-jarvis-text">{quote.ask.toFixed(2)}</span>
          <span className="text-xs px-2 py-0.5 rounded bg-jarvis-elevated">
            Spread: {quote.spread.toFixed(2)}
          </span>
        </div>
      )}

      {/* Decision Badge */}
      {decision && decision.action !== 'HOLD' && (
        <div className="absolute top-4 right-4 z-10">
          <span className={clsx(
            'px-3 py-1 rounded-lg text-xs font-bold',
            decision.action === 'BUY' ? 'bg-green-500/20 text-green-400 border border-green-500/30' : 'bg-red-500/20 text-red-400 border border-red-500/30'
          )}>
            {decision.action} {decision.confidence.toFixed(0)}%
          </span>
        </div>
      )}
    </div>
  )
}

import { useEffect, useRef } from 'react'
import { createChart, IChartApi, Time } from 'lightweight-charts'
import { EquityPoint } from '@/types'

interface EquityChartProps {
  data: EquityPoint[]
  height?: number
  className?: string
}

export function EquityChart({ data, height = 200, className }: EquityChartProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const chartRef = useRef<IChartApi | null>(null)

  useEffect(() => {
    if (!containerRef.current || data.length === 0) return

    const chart = createChart(containerRef.current, {
      layout: {
        background: { type: 'solid', color: '#0a0e17' },
        textColor: '#9ca3af',
        fontSize: 10,
        fontFamily: 'JetBrains Mono, monospace',
      },
      grid: {
        vertLines: { color: '#1f2937', visible: false },
        horzLines: { color: '#1f2937' },
      },
      crosshair: { mode: 0 },
      rightPriceScale: {
        borderVisible: false,
        scaleMargins: { top: 0.1, bottom: 0.1 },
      },
      timeScale: {
        borderVisible: false,
        timeVisible: false,
      },
      handleScroll: { mouseWheel: true, pressedMouseMove: true },
      handleScale: { mouseWheel: true, pinch: true },
    })

    chartRef.current = chart

    const series = chart.addLineSeries({
      color: '#2b6bff',
      lineWidth: 1.5,
      priceLineVisible: true,
      priceLineColor: '#2b6bff',
      priceLineWidth: 1,
      lastValueVisible: true,
    })

    const formatted = data.map(d => ({
      time: d.time as Time,
      value: d.equity,
    }))

    series.setData(formatted)

    // Add gradient area
    const areaSeries = chart.addAreaSeries({
      topColor: 'rgba(43, 107, 255, 0.3)',
      bottomColor: 'rgba(43, 107, 255, 0)',
      lineColor: 'rgba(43, 107, 255, 0)',
      priceScaleId: '',
    })
    areaSeries.setData(formatted)

    const resizeObserver = new ResizeObserver(() => {
      chart.resize(containerRef.current!.clientWidth, height)
    })
    resizeObserver.observe(containerRef.current)

    return () => {
      resizeObserver.disconnect()
      chart.remove()
    }
  }, [data, height])

  return <div ref={containerRef} className={className} style={{ height, width: '100%' }} />
}

import { useEffect, useState, useMemo } from 'react'
import { useEngineStore } from '@/store/engineStore'
import { useEngineStatus, useLatestDecision, useEquity, useRiskSnapshot, useHealth } from '@/services/api'
import { TradingChart } from '@/components/charts/TradingChart'
import { EquityChart } from '@/components/charts/EquityChart'
import { 
  TrendingUp, TrendingDown, Minus, AlertTriangle, 
  Shield, Gauge, Zap, Target, Activity, ChevronDown, ChevronUp
} from 'lucide-react'
import { clsx } from 'clsx'
import { Decision, Equity } from '@/types'

interface EquityPoint { time: number; equity: number }

export function Dashboard() {
  const { 
    candles, 
    quote, 
    latestDecision, 
    equity, 
    riskSnapshot, 
    health,
    running,
    paused,
    connected,
  } = useEngineStore()

  // React Query data (fallback when WS not connected)
  const { data: engineStatus } = useEngineStatus()
  const { data: decisionData } = useLatestDecision()
  const { data: equityData } = useEquity()
  const { data: riskData } = useRiskSnapshot()
  const { data: healthData } = useHealth()

  // Merge WS + REST data
  const decision = latestDecision || decisionData
  const equityMerged = equity || equityData
  const risk = riskSnapshot || riskData
  const healthStatus = health || healthData

  const [showVolume, setShowVolume] = useState(true)
  const [showEMA8, setShowEMA8] = useState(true)
  const [showEMA21, setShowEMA21] = useState(true)
  const [showEMA50, setShowEMA50] = useState(false)
  const [timeframe, setTimeframe] = useState('M1')
  const [collapsedPanels, setCollapsedPanels] = useState<Record<string, boolean>>({
    metrics: false,
    filters: false,
    bridge: true,
  })

  // Generate mock EMA data for demo (replace with real indicator calculation)
  const emas = useMemo(() => {
    if (candles.size === 0) return undefined
    const tfCandles = candles.get(timeframe) || []
    if (tfCandles.length < 50) return undefined

    const closes = tfCandles.map(c => c.close)
    const ema8 = calculateEMA(closes, 8)
    const ema21 = calculateEMA(closes, 21)
    const ema50 = calculateEMA(closes, 50)
    const vol = tfCandles.map(c => c.volume)

    return { ema8, ema21, ema50, volume: vol }
  }, [candles, timeframe])

  // Equity history for chart (mock for now)
  const equityHistory = useMemo((): EquityPoint[] => {
    if (!equityMerged) return []
    const now = Date.now() / 1000
    const points = []
    let eq = equityMerged.equity - equityMerged.day_pnl
    for (let i = 100; i >= 0; i--) {
      eq += (Math.random() - 0.48) * 50
      points.push({ time: now - i * 3600, equity: eq })
    }
    points.push({ time: now, equity: equityMerged.equity })
    return points
  }, [equityMerged])

  return (
    <div className="h-full flex flex-col gap-6">
      {/* Top Stats Bar */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-8 gap-4">
        <StatCard
          icon={running && !paused ? <Zap className="w-5 h-5 text-jarvis-success" /> : <Zap className="w-5 h-5 text-jarvis-warning" />}
          label="Stato Motore"
          value={running ? (paused ? 'PAUSA' : 'ATTIVO') : 'FERMO'}
          delta={running ? (paused ? 'In pausa' : 'Operativo') : 'Non avviato'}
          deltaPositive={running && !paused}
        />

        <StatCard
          icon={connected ? <Activity className="w-5 h-5 text-jarvis-success" /> : <Activity className="w-5 h-5 text-jarvis-danger" />}
          label="WebSocket"
          value={connected ? 'Connesso' : 'Disconnesso'}
          delta={connected ? 'Real-time attivo' : 'Solo polling REST'}
          deltaPositive={connected}
        />

        <StatCard
          icon={equityMerged ? <TrendingUp className="w-5 h-5 text-jarvis-success" /> : <TrendingUp className="w-5 h-5 text-jarvis-textMuted" />}
          label="Equity"
          value={equityMerged ? `$${equityMerged.equity.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}` : 'N/A'}
          delta={equityMerged ? `$${equityMerged.day_pnl >= 0 ? '+' : ''}${equityMerged.day_pnl.toFixed(2)} oggi` : 'N/A'}
          deltaPositive={equityMerged ? equityMerged.day_pnl >= 0 : false}
        />

        <StatCard
          icon={<Target className="w-5 h-5 text-jarvis-primary" />}
          label="Posizioni"
          value={equityMerged ? equityMerged.positions.toString() : '0'}
          delta={equityMerged ? `PnL Sett: $${equityMerged.week_pnl.toFixed(2)}` : 'N/A'}
          deltaPositive={equityMerged ? equityMerged.week_pnl >= 0 : false}
        />

        <StatCard
          icon={<Shield className="w-5 h-5 text-jarvis-primary" />}
          label="Risk %"
          value={risk.daily_pnl !== undefined ? `${((risk.daily_pnl / (risk.day_start_equity || 1)) * 100).toFixed(2)}%` : 'N/A'}
          delta={`Cap: ${risk.max_daily_loss_pct || 3}%`}
          deltaPositive={risk.daily_pnl >= (-(risk.day_start_equity || 1) * (risk.max_daily_loss_pct || 3) / 100)}
        />

        <StatCard
          icon={<Gauge className="w-5 h-5 text-jarvis-warning" />}
          label="Health"
          value={healthStatus?.overall || 'unknown'}
          delta={`${Object.keys(healthStatus?.checks || {}).filter(k => healthStatus.checks[k].status === 'healthy').length} / ${Object.keys(healthStatus?.checks || {}).length} checks OK`}
          deltaPositive={healthStatus?.overall === 'healthy'}
        />

        <StatCard
          icon={<AlertTriangle className="w-5 h-5 text-jarvis-warning" />}
          label="Errori"
          value={engineStatus?.error_count || 0}
          delta="Reset all'avvio"
        />

        <StatCard
          icon={<Target className="w-5 h-5 text-jarvis-secondary" />}
          label="Ultimo Segnale"
          value={decision ? decision.action : 'N/A'}
          delta={decision ? `${decision.confidence.toFixed(0)}% confidenza` : 'Nessun segnale'}
          deltaPositive={decision?.action === 'BUY'}
        />
      </div>

      {/* Main Content */}
      <div className="flex-1 flex gap-6 min-h-0">
        {/* Left: Chart */}
        <div className="flex-1 lg:w-2/3 flex flex-col gap-4 min-w-0">
          <div className="card flex-1 flex flex-col min-h-0">
            <TradingChart
              candles={Array.from(candles.get(timeframe) || [])}
              quote={quote}
              decision={decision}
              emas={emas}
              timeframe={timeframe}
              onTimeframeChange={setTimeframe}
              showVolume={showVolume}
              showEMA8={showEMA8}
              showEMA21={showEMA21}
              showEMA50={showEMA50}
              className="flex-1"
            />
          </div>

          {/* Equity Mini Chart */}
          <div className="card" style={{ height: 150 }}>
            <div className="flex items-center justify-between mb-3">
              <h3 className="font-medium text-jarvis-text">Curva Equity (24h)</h3>
              <span className="text-xs text-jarvis-textMuted">
                {equityMerged ? `$${equityMerged.equity.toFixed(2)}` : 'N/A'}
              </span>
            </div>
            <EquityChart data={equityHistory} height={100} />
          </div>
        </div>

        {/* Right: Panels */}
        <div className="w-full lg:w-1/3 flex flex-col gap-4 min-w-0">
          {/* Decision Panel */}
          <CollapsiblePanel title="Decisione Attuale" icon={Target} defaultOpen>
            <DecisionPanel decision={decision} quote={quote} />
          </CollapsiblePanel>

          {/* Metrics Panel */}
          <CollapsiblePanel 
            title="Metriche Rischio" 
            icon={Gauge} 
            defaultOpen={!collapsedPanels.metrics}
            collapsed={collapsedPanels.metrics}
            onToggle={() => setCollapsedPanels(p => ({ ...p, metrics: !p.metrics }))}
          >
            <MetricsPanel risk={risk} equity={equityMerged} />
          </CollapsiblePanel>

          {/* Filters Panel */}
          <CollapsiblePanel 
            title="Filtri d'Ingresso" 
            icon={Shield} 
            defaultOpen={!collapsedPanels.filters}
            collapsed={collapsedPanels.filters}
            onToggle={() => setCollapsedPanels(p => ({ ...p, filters: !p.filters }))}
          >
            <FiltersPanel decision={decision} />
          </CollapsiblePanel>

          {/* Bridge Panel */}
          <CollapsiblePanel 
            title="Ponte EA" 
            icon={Zap} 
            defaultOpen={!collapsedPanels.bridge}
            collapsed={collapsedPanels.bridge}
            onToggle={() => setCollapsedPanels(p => ({ ...p, bridge: !p.bridge }))}
          >
            <BridgePanel health={healthStatus} />
          </CollapsiblePanel>
        </div>
      </div>
    </div>
  )
}

// Helper Components
function StatCard({ icon, label, value, delta, deltaPositive }: any) {
  return (
    <div className="card">
      <div className="flex items-start gap-3">
        <div className="p-2 bg-jarvis-elevated rounded-lg">{icon}</div>
        <div className="flex-1 min-w-0">
          <p className="text-xs text-jarvis-textMuted uppercase tracking-wide">{label}</p>
          <p className="text-xl font-bold font-mono text-jarvis-text truncate">{value}</p>
          <p className={clsx('text-xs font-medium mt-1', deltaPositive ? 'text-jarvis-success' : 'text-jarvis-danger')}>
            {delta}
          </p>
        </div>
      </div>
    </div>
  )
}

function CollapsiblePanel({ title, icon: Icon, children, defaultOpen = true, collapsed = false, onToggle }: any) {
  const [open, setOpen] = useState(defaultOpen)
  const isCollapsed = collapsed !== undefined ? collapsed : !open

  return (
    <div className="card flex flex-col">
      <button
        onClick={() => { setOpen(!open); onToggle?.() }}
        className="flex items-center gap-3 w-full py-2 px-1"
      >
        <Icon className="w-5 h-5 text-jarvis-primary" />
        <span className="font-medium text-jarvis-text flex-1">{title}</span>
        <ChevronDown className={clsx('w-4 h-4 text-jarvis-textMuted transition-transform', open && 'rotate-180')} />
      </button>
      <div className={clsx('overflow-hidden transition-all duration-200', isCollapsed ? 'max-h-0 opacity-0 pt-0' : 'max-h-96 opacity-100')}>
        <div className="pt-2 border-t border-jarvis-border">{children}</div>
      </div>
    </div>
  )
}

function DecisionPanel({ decision, quote }: { decision: Decision | null; quote: Quote | null }) {
  if (!decision) {
    return <div className="text-center py-8 text-jarvis-textMuted">In attesa del primo segnale...</div>
  }

  const actionColors = {
    BUY: 'text-jarvis-success',
    SELL: 'text-jarvis-danger',
    HOLD: 'text-jarvis-warning',
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <span className={clsx('text-3xl font-bold', actionColors[decision.action as keyof typeof actionColors] || 'text-jarvis-text')}>
          {decision.action}
        </span>
        <span className="text-sm px-3 py-1 rounded-full bg-jarvis-elevated font-mono">
          {decision.confidence.toFixed(1)}%
        </span>
      </div>

      <div className="grid grid-cols-2 gap-3 text-sm">
        <div>
          <p className="text-jarvis-textMuted">Bid / Ask</p>
          <p className="font-mono text-jarvis-text">
            {quote ? `${quote.bid.toFixed(2)} / ${quote.ask.toFixed(2)}` : 'N/A'}
