          <InputField label="Fees %" type="number" value={config.fees * 10000} onChange={v => setConfig({...config, fees: parseFloat(v) / 10000})} step="1" suffix="bps" />
          <InputField label="Slippage %" type="number" value={config.slippage * 10000} onChange={v => setConfig({...config, slippage: parseFloat(v) / 10000})} step="1" suffix="bps" />
