          disabled={runBacktest.isPending || status?.status === 'running'}
          className="btn-primary w-full md:w-auto gap-2"
        >
          {runBacktest.isPending || status?.status === 'running' ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              {status?.status === 'running' ? 'In esecuzione...' : 'Avvio...'}
