function MetricCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="p-4 bg-jarvis-elevated rounded-lg border border-jarvis-border">
      <p className="text-xs text-jarvis-textMuted uppercase tracking-wide">{label}</p>
      <p className="text-xl font-bold font-mono text-jarvis-text mt-1">{value}</p>
    </div>
  )
