function formatMetricName(key: string): string {
  return key
    .replace(/_/g, ' ')
    .replace(/\b\w/g, c => c.toUpperCase())
}

function formatMetricValue(key: string, value: number): string {
  if (key.includes('return') || key.includes('drawdown') || key.includes('rate') || key.includes('factor') || key.includes('win')) {
    return `${value.toFixed(2)}%`
  }
  if (key.includes('trade') || key.includes('count')) {
    return value.toFixed(0)
  }
  if (key.includes('sharpe') || key.includes('sortino') || key.includes('calmar') || key.includes('expectancy') || key.includes('rr') || key.includes('multiple')) {
    return value.toFixed(3)
  }
  return value.toFixed(2)
}

import { useState, useEffect } from 'react'
import { api } from '@/services/api'
import { Save, Loader2, RefreshCw, Download, Upload, AlertTriangle, Shield } from 'lucide-react'
import { clsx } from 'clsx'
import toast from 'react-hot-toast'

interface ConfigParam {
  name: string
  value: any
  type: string
  min?: number
  max?: number
  choices?: string[]
  description?: string
  category: string
}

const CATEGORIES = [
  'Generale', 'Timeframe', 'Strategia', 'Target Engine', 
  'Regime', 'Filtri', 'Scoring', 'Mercato Morto', 
  'Kill Zone', 'Sessioni', 'News', 'COT', 'AI News', 
  'Rischio', 'Runtime', 'Circuit Breaker'
]

export function Settings() {
  const [params, setParams] = useState<ConfigParam[]>([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [activeCategory, setActiveCategory] = useState('Generale')
  const [search, setSearch] = useState('')
  const [showAdvanced, setShowAdvanced] = useState(false)

  useEffect(() => {
    loadConfig()
  }, [])

  const loadConfig = async () => {
    try {
      const data = await api.getConfig()
      const formatted = Object.entries(data).map(([name, value]) => ({
        name,
        value,
        type: typeof value === 'boolean' ? 'boolean' : 
              typeof value === 'number' ? 'number' : 'string',
        category: categorizeParam(name),
      }))
      setParams(formatted)
    } catch (e: any) {
      toast.error('Errore caricamento config: ' + e.message)
    } finally {
      setLoading(false)
    }
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      const updates = params.reduce((acc, p) => {
        acc[p.name] = p.value
        return acc
      }, {} as Record<string, any>)
      await api.updateConfig(updates)
      toast.success('Configurazione salvata. Riavvia il motore per applicare le modifiche.')
    } catch (e: any) {
      toast.error('Errore salvataggio: ' + e.message)
    } finally {
      setSaving(false)
    }
  }

  const handleReset = async () => {
    if (!confirm('Ripristinare configurazione di default?')) return
    try {
      await api.updateConfig({}, false)
      await loadConfig()
      toast.success('Configurazione ripristinata')
    } catch (e: any) {
      toast.error(e.message)
    }
  }

  const exportConfig = () => {
    const data = params.reduce((acc, p) => { acc[p.name] = p.value; return acc }, {})
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `jarvis-config-${new Date().toISOString().split('T')[0]}.json`
    a.click()
    URL.revokeObjectURL(url)
  }

  const filteredParams = params.filter(p => 
    (activeCategory === 'Tutte' || p.category === activeCategory) &&
    (p.name.toLowerCase().includes(search.toLowerCase()) ||
     JSON.stringify(p.value).toLowerCase().includes(search.toLowerCase()))
  )

  if (loading) {
    return <div className="flex items-center justify-center h-64"><Loader2 className="w-8 h-8 animate-spin text-jarvis-primary" /></div>
  }

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-jarvis-text">Configurazione</h1>
          <p className="text-jarvis-textMuted">Parametri motore JARVIS v20</p>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={exportConfig} className="btn-secondary gap-2">
            <Download className="w-4 h-4" />
            Esporta JSON
          </button>
          <button onClick={handleReset} className="btn-ghost gap-2 text-jarvis-warning">
            <RefreshCw className="w-4 h-4" />
            Default
          </button>
          <button onClick={handleSave} disabled={saving} className="btn-primary gap-2">
            {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
            Salva
          </button>
        </div>
      </div>

      {/* Search & Filters */}
      <div className="card flex flex-col gap-4">
        <div className="flex flex-wrap gap-4">
          <div className="flex-1 min-w-[200px] relative">
            <input
              type="text"
              placeholder="Cerca parametro..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="input pl-10"
            />
            <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-jarvis-textMuted" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>
          <select
            value={activeCategory}
            onChange={e => setActiveCategory(e.target.value)}
            className="input w-auto min-w-[150px]"
          >
            <option value="Tutte">Tutte le categorie</option>
            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <label className="flex items-center gap-2 cursor-pointer text-sm">
            <input type="checkbox" checked={showAdvanced} onChange={e => setShowAdvanced(e.target.checked)} className="w-4 h-4 accent-jarvis-primary" />
            Mostra avanzati
          </label>
        </div>
      </div>

      {/* Params Grid */}
      <div className="card">
        <div className="grid gap-4" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))' }}>
          {filteredParams.map(param => (
            <ParamInput key={param.name} param={param} onChange={handleParamChange} advanced={!showAdvanced && isAdvanced(param.name)} />
          ))}
        </div>

        {filteredParams.length === 0 && (
          <div className="text-center py-12 text-jarvis-textMuted">
            Nessun parametro trovato per la categoria "{activeCategory}" e ricerca "{search}"
          </div>
        )}
      </div>

      {/* Info */}
      <div className="card border-jarvis-warning/30 bg-jarvis-warning/5">
        <div className="flex items-start gap-3">
          <AlertTriangle className="w-5 h-5 text-jarvis-warning mt-0.5" />
          <div>
            <p className="font-medium text-jarvis-warning">Modifiche richiedono riavvio motore</p>
            <p className="text-sm text-jarvis-textMuted mt-1">
              Alcuni parametri (timeframe, feed, risk engine) richiedono lo stop/start del motore per prendere effetto.
              La configurazione viene salvata in <code className="font-mono bg-jarvis-elevated px-1 rounded">jarvis_data/config.json</code>
              con backup automatico.
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

function ParamInput({ param, onChange, advanced }: { param: ConfigParam; onChange: (name: string, value: any) => void; advanced: boolean }) {
  if (advanced) return null

  const { name, value, type, min, max, choices } = param

  if (type === 'boolean') {
    return (
      <label className="flex items-center gap-3 p-3 bg-jarvis-elevated rounded-lg border border-jarvis-border hover:border-jarvis-primary/30 transition-colors cursor-pointer">
        <input
          type="checkbox"
          checked={value}
          onChange={e => onChange(name, e.target.checked)}
          className="w-5 h-5 accent-jarvis-primary"
        />
        <div className="flex-1">
          <p className="font-medium text-jarvis-text">{formatName(name)}</p>
          <p className="text-xs text-jarvis-textMuted">{param.description || 'Booleano'}</p>
        </div>
      </label>
    )
  }

  if (choices && choices.length > 0) {
    return (
      <div className="p-3 bg-jarvis-elevated rounded-lg border border-jarvis-border">
        <label className="block text-sm font-medium text-jarvis-text mb-1">{formatName(name)}</label>
        <select
          value={value}
          onChange={e => onChange(name, e.target.value)}
          className="input mt-1"
        >
          {choices.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        {param.description && <p className="text-xs text-jarvis-textMuted mt-1">{param.description}</p>}
      </div>
    )
  }

  if (type === 'number') {
    return (
      <div className="p-3 bg-jarvis-elevated rounded-lg border border-jarvis-border">
        <label className="block text-sm font-medium text-jarvis-text mb-1">{formatName(name)}</label>
        <input
          type="number"
          value={value}
          onChange={e => onChange(name, parseFloat(e.target.value) || 0)}
          min={min}
          max={max}
          step={Number.isInteger(value) ? 1 : 0.01}
          className="input mt-1"
        />
        {param.description && <p className="text-xs text-jarvis-textMuted mt-1">{param.description}</p>}
      </div>
    )
  }

  return (
    <div className="p-3 bg-jarvis-elevated rounded-lg border border-jarvis-border">
      <label className="block text-sm font-medium text-jarvis-text mb-1">{formatName(name)}</label>
      <input
        type="text"
        value={value}
        onChange={e => onChange(name, e.target.value)}
        className="input mt-1 font-mono"
      />
      {param.description && <p className="text-xs text-jarvis-textMuted mt-1">{param.description}</p>}
    </div>
  )
}

