function formatName(name: string): string {
  return name
    .replace(/_/g, ' ')
    .replace(/\b\w/g, c => c.toUpperCase())
}

function categorizeParam(name: string): string {
  const prefixes: Record<string, string> = {
    symbol_default: 'Generale',
    intervallo: 'Generale',
    tf_: 'Timeframe',
    candles_: 'Timeframe',
    min_confidenza: 'Strategia',
