    cooldown: 'Rischio',
    commission: 'Rischio',
    max_spread_atr: 'Rischio',
    theme: 'Runtime',
    signal_log: 'Runtime',
    max_feed: 'Circuit Breaker',
    max_spread_anomaly: 'Circuit Breaker',
    max_consecutive: 'Circuit Breaker',
  }

  for (const [prefix, cat] of Object.entries(prefixes)) {
    if (name.startsWith(prefix)) return cat
  }
  return 'Altro'
}

function isAdvanced(name: string): boolean {
  const advancedPrefixes = [
    'swing_', 'min_stop_', 'rr_min', 'min_prob', 'min_expectancy', 'cost_per',
    'max_hold', 'time_stop', 'regime_', 'filters_', 'max_overextension', 'max_bar_atr',
    'scoring_', 'peso_', 'score_', 'min_vol', 'vol_atr', 'vol_avg',
    'killzone_', 'ai_', 'max_feed', 'max_spread_anomaly', 'max_consecutive',
    'commission', 'theme', 'signal_log'
  ]
  return advancedPrefixes.some(p => name.startsWith(p))
}

