input.content:
"""
JARVIS v20 - TA Library Wrapper (130+ Technical Indicators)
=============================================================

Wrapper per 'ta' library (bukosabino/ta) - 130+ indicatori tecnici
pandas-native, vettorizzati, compatibili con JARVIS indicators.py.

Install: pip install ta
Docs: https://technical-analysis-library-in-python.readthedocs.io

Indicatori disponibili per categoria:
- Trend: ADX, Aroon, MACD, MA, EMA, SMA, WMA, Ichimoku, Parabolic SAR, Vortex
- Momentum: RSI, Stochastic, Williams %R, ROC, MFI, TSI, Ultimate Oscillator
- Volatility: ATR, Bollinger Bands, Keltner Channel, Donchian Channel, Standard Deviation
- Volume: OBV, CMF, FI, EOM, VPT, NVI, PVI
- Others: Pivot Points, Fibonacci, Z-Score, Linear Regression
"""

from __future__ import annotations

import warnings
from typing import Any, Dict, List, Optional, Union

import numpy as np
import pandas as pd

try:
    import ta
    from ta import add_all_ta_features
    from ta.trend import (
        ADXIndicator, AroonIndicator, MACD, CCIIndicator, 
        EMAIndicator, SMAIndicator, WMAIndicator, 
        IchimokuIndicator, PSARIndicator, VortexIndicator,
        TRIXIndicator, MassIndexIndicator, DPOIndicator
    )
    from ta.momentum import (
        RSIIndicator, StochasticOscillator, WilliamsRIndicator,
        ROCIndicator, MFIIndicator, TSIIndicator, 
        UltimateOscillator, StochRSIIndicator, KSTIndicator
    )
    from ta.volatility import (
        AverageTrueRange, BollingerBands, KeltnerChannel,
        DonchianChannel, StandardDeviation, 
        AverageTrueRangePercent, UlcerIndex
    )
    from ta.volume import (
        OnBalanceVolumeIndicator, ChaikinMoneyFlowIndicator,
        ForceIndexIndicator, EaseOfMovementIndicator,
        VolumePriceTrendIndicator, NegativeVolumeIndexIndicator,
        PositiveVolumeIndexIndicator
    )
    from ta.others import (
        DailyReturnIndicator, LogReturnIndicator, 
        CumulativeReturnIndicator
    )
    HAS_TA = True
except ImportError:
    HAS_TA = False
    ta = None

from .config import Settings

warnings.filterwarnings("ignore")


class TALibWrapper:
    """
    Wrapper unificato per ta library.

    Fornisce interfaccia compatibile con indicators.py esistente
    ma con 130+ indicatori vettorizzati.
    """

    def __init__(self, settings: Optional[Settings] = None):
        if not HAS_TA:
            raise RuntimeError("ta library non installato: pip install ta")

        self.settings = settings or Settings()
        self._cache: Dict[str, Any] = {}

    def add_all_indicators(
        self,
        df: pd.DataFrame,
        open_col: str = "Open",
        high_col: str = "High",
        low_col: str = "Low",
        close_col: str = "Close",
        volume_col: str = "Volume",
        fillna: bool = True
    ) -> pd.DataFrame:
        """
        Aggiunge TUTTI gli indicatori TA al DataFrame.

        Returns DataFrame con 130+ nuove colonne.
        """
        return add_all_ta_features(
            df,
            open=open_col,
            high=high_col,
            low=low_col,
            close=close_col,
            volume=volume_col,
            fillna=fillna
        )

    # ─── TREND INDICATORS ───

    def adx(self, high: pd.Series, low: pd.Series, close: pd.Series, window: int = 14) -> pd.Series:
        """Average Directional Index."""
        return ADXIndicator(high, low, close, window=window).adx()

    def adx_pos(self, high: pd.Series, low: pd.Series, close: pd.Series, window: int = 14) -> pd.Series:
        """+DI."""
        return ADXIndicator(high, low, close, window=window).adx_pos()

    def adx_neg(self, high: pd.Series, low: pd.Series, close: pd.Series, window: int = 14) -> pd.Series:
        """-DI."""
        return ADXIndicator(high, low, close, window=window).adx_neg()

    def aroon_up(self, high: pd.Series, low: pd.Series, window: int = 25) -> pd.Series:
        """Aroon Up."""
        return AroonIndicator(high, low, window=window).aroon_up()

    def aroon_down(self, high: pd.Series, low: pd.Series, window: int = 25) -> pd.Series:
        """Aroon Down."""
        return AroonIndicator(high, low, window=window).aroon_down()

    def aroon_indicator(self, high: pd.Series, low: pd.Series, window: int = 25) -> pd.Series:
        """Aroon Indicator (Up - Down)."""
        return AroonIndicator(high, low, window=window).aroon_indicator()

    def macd(
        self, 
        close: pd.Series, 
        window_slow: int = 26, 
        window_fast: int = 12, 
        window_sign: int = 9
    ) -> Dict[str, pd.Series]:
        """MACD completo."""
        macd = MACD(close, window_slow, window_fast, window_sign)
        return {
            "macd": macd.macd(),
            "macd_signal": macd.macd_signal(),
            "macd_diff": macd.macd_diff(),
        }

    def ema(self, close: pd.Series, window: int) -> pd.Series:
        """Exponential Moving Average."""
        return EMAIndicator(close, window=window).ema_indicator()

    def sma(self, close: pd.Series, window: int) -> pd.Series:
        """Simple Moving Average."""
        return SMAIndicator(close, window=window).sma_indicator()

    def wma(self, close: pd.Series, window: int) -> pd.Series:
        """Weighted Moving Average."""
        return WMAIndicator(close, window=window).wma_indicator()

    def ichimoku(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window1: int = 9,
        window2: int = 26,
        window3: int = 52,
    ) -> Dict[str, pd.Series]:
        """Ichimoku Kinko Hyo."""
        ichi = IchimokuIndicator(high, low, window1, window2, window3)
        return {
            "tenkan_sen": ichi.ichimoku_conversion_line(),
            "kijun_sen": ichi.ichimoku_base_line(),
            "senkou_span_a": ichi.ichimoku_a(),
            "senkou_span_b": ichi.ichimoku_b(),
            "chikou_span": ichi.ichimoku_chikou_span(),
        }

    def psar(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        step: float = 0.02,
        max_step: float = 0.2,
    ) -> Dict[str, pd.Series]:
        """Parabolic SAR."""
        psar = PSARIndicator(high, low, close, step, max_step)
        return {
            "psar": psar.psar(),
            "psar_up": psar.psar_up(),
            "psar_down": psar.psar_down(),
            "psar_up_indicator": psar.psar_up_indicator(),
            "psar_down_indicator": psar.psar_down_indicator(),
        }

    def vortex(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window: int = 14,
    ) -> Dict[str, pd.Series]:
        """Vortex Indicator."""
        vi = VortexIndicator(high, low, close, window)
        return {
            "vi_pos": vi.vortex_indicator_pos(),
            "vi_neg": vi.vortex_indicator_neg(),
            "vi_diff": vi.vortex_indicator_pos() - vi.vortex_indicator_neg(),
        }

    def trix(self, close: pd.Series, window: int = 15) -> pd.Series:
        """TRIX."""
        return TRIXIndicator(close, window=window).trix()

    def mass_index(self, high: pd.Series, low: pd.Series, window: int = 25) -> pd.Series:
        """Mass Index."""
        return MassIndexIndicator(high, low, window=window).mass_index()

    def dpo(self, close: pd.Series, window: int = 20) -> pd.Series:
        """Detrended Price Oscillator."""
        return DPOIndicator(close, window=window).dpo()

    def cci(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window: int = 20,
    ) -> pd.Series:
        """Commodity Channel Index."""
        return CCIIndicator(high, low, close, window=window).cci()

    # ─── MOMENTUM INDICATORS ───

    def rsi(self, close: pd.Series, window: int = 14) -> pd.Series:
        """Relative Strength Index."""
        return RSIIndicator(close, window=window).rsi()

    def stoch(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window: int = 14,
        smooth_window: int = 3,
    ) -> Dict[str, pd.Series]:
        """Stochastic Oscillator."""
        stoch = StochasticOscillator(high, low, close, window, smooth_window)
        return {
            "stoch": stoch.stoch(),
            "stoch_signal": stoch.stoch_signal(),
        }

    def stoch_rsi(
        self,
        close: pd.Series,
        window: int = 14,
        smooth1: int = 3,
        smooth2: int = 3,
    ) -> Dict[str, pd.Series]:
        """Stochastic RSI."""
        srsi = StochRSIIndicator(close, window, smooth1, smooth2)
        return {
            "stoch_rsi": srsi.stochrsi(),
            "stoch_rsi_d": srsi.stochrsi_d(),
            "stoch_rsi_k": srsi.stochrsi_k(),
        }

    def williams_r(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window: int = 14,
    ) -> pd.Series:
        """Williams %R."""
        return WilliamsRIndicator(high, low, close, window=window).williams_r()

    def roc(self, close: pd.Series, window: int = 12) -> pd.Series:
        """Rate of Change."""
        return ROCIndicator(close, window=window).roc()

    def mfi(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        volume: pd.Series,
        window: int = 14,
    ) -> pd.Series:
        """Money Flow Index."""
        return MFIIndicator(high, low, close, volume, window=window).money_flow_index()

    def tsi(
        self,
        close: pd.Series,
        window_slow: int = 25,
        window_fast: int = 13,
    ) -> pd.Series:
        """True Strength Index."""
        return TSIIndicator(close, window_slow, window_fast).tsi()

    def ultimate_oscillator(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window1: int = 7,
        window2: int = 14,
        window3: int = 28,
    ) -> pd.Series:
        """Ultimate Oscillator."""
        return UltimateOscillator(high, low, close, window1, window2, window3).ultimate_oscillator()

    def kst(
        self,
        close: pd.Series,
        roc1: int = 10,
        roc2: int = 15,
        roc3: int = 20,
        roc4: int = 30,
        window1: int = 10,
        window2: int = 10,
        window3: int = 10,
        window4: int = 15,
    ) -> Dict[str, pd.Series]:
        """Know Sure Thing."""
        kst = KSTIndicator(close, roc1, roc2, roc3, roc4, window1, window2, window3, window4)
        return {
            "kst": kst.kst(),
            "kst_signal": kst.kst_signal(),
            "kst_diff": kst.kst_diff(),
        }

    # ─── VOLATILITY INDICATORS ───

    def atr(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window: int = 14,
    ) -> pd.Series:
        """Average True Range."""
        return AverageTrueRange(high, low, close, window=window).average_true_range()

    def atr_percent(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window: int = 14,
    ) -> pd.Series:
        """ATR as percentage of close."""
        return AverageTrueRangePercent(high, low, close, window=window).average_true_range_percent()

    def bollinger_bands(
        self,
        close: pd.Series,
        window: int = 20,
        window_dev: int = 2,
    ) -> Dict[str, pd.Series]:
        """Bollinger Bands."""
        bb = BollingerBands(close, window=window, window_dev=window_dev)
        return {
            "bb_high": bb.bollinger_hband(),
            "bb_mid": bb.bollinger_mavg(),
            "bb_low": bb.bollinger_lband(),
            "bb_width": bb.bollinger_wband(),
            "bb_pct": bb.bollinger_pband(),
        }

    def keltner_channel(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window: int = 20,
        window_atr: int = 10,
        multiplier: float = 2.0,
    ) -> Dict[str, pd.Series]:
        """Keltner Channel."""
        kc = KeltnerChannel(high, low, close, window, window_atr, multiplier)
        return {
            "kc_high": kc.keltner_channel_hband(),
            "kc_mid": kc.keltner_channel_mband(),
            "kc_low": kc.keltner_channel_lband(),
            "kc_width": kc.keltner_channel_wband(),
            "kc_pct": kc.keltner_channel_pband(),
        }

    def donchian_channel(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        window: int = 20,
    ) -> Dict[str, pd.Series]:
        """Donchian Channel."""
        dc = DonchianChannel(high, low, close, window)
        return {
            "dc_high": dc.donchian_channel_hband(),
            "dc_mid": dc.donchian_channel_mband(),
            "dc_low": dc.donchian_channel_lband(),
            "dc_width": dc.donchian_channel_wband(),
            "dc_pct": dc.donchian_channel_pband(),
        }

    def std_dev(self, close: pd.Series, window: int = 20) -> pd.Series:
        """Standard Deviation."""
        return StandardDeviation(close, window=window).standard_deviation()

    def ulcer_index(self, close: pd.Series, window: int = 14) -> pd.Series:
        """Ulcer Index."""
        return UlcerIndex(close, window=window).ulcer_index()

    # ─── VOLUME INDICATORS ───

    def obv(self, close: pd.Series, volume: pd.Series) -> pd.Series:
        """On Balance Volume."""
        return OnBalanceVolumeIndicator(close, volume).on_balance_volume()

    def cmf(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        volume: pd.Series,
        window: int = 20,
    ) -> pd.Series:
        """Chaikin Money Flow."""
        return ChaikinMoneyFlowIndicator(high, low, close, volume, window=window).chaikin_money_flow()

    def force_index(self, close: pd.Series, volume: pd.Series, window: int = 13) -> pd.Series:
        """Force Index."""
        return ForceIndexIndicator(close, volume, window=window).force_index()

    def ease_of_movement(
        self,
        high: pd.Series,
        low: pd.Series,
        volume: pd.Series,
        window: int = 14,
    ) -> pd.Series:
        """Ease of Movement."""
        return EaseOfMovementIndicator(high, low, volume, window=window).ease_of_movement()

    def vpt(self, close: pd.Series, volume: pd.Series) -> pd.Series:
        """Volume Price Trend."""
        return VolumePriceTrendIndicator(close, volume).volume_price_trend()

    def nvi(self, close: pd.Series, volume: pd.Series) -> pd.Series:
        """Negative Volume Index."""
        return NegativeVolumeIndexIndicator(close, volume).negative_volume_index()

    def pvi(self, close: pd.Series, volume: pd.Series) -> pd.Series:
        """Positive Volume Index."""
        return PositiveVolumeIndexIndicator(close, volume).positive_volume_index()

    # ─── UTILITY ───

    def daily_return(self, close: pd.Series) -> pd.Series:
        """Daily Return."""
        return DailyReturnIndicator(close).daily_return()

    def log_return(self, close: pd.Series) -> pd.Series:
        """Log Return."""
        return LogReturnIndicator(close).log_return()

    def cumulative_return(self, close: pd.Series) -> pd.Series:
        """Cumulative Return."""
        return CumulativeReturnIndicator(close).cumulative_return()

    # ─── COMPOSITE / STRATEGY SPECIFIC ───

    def squeeze_momentum(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        bb_window: int = 20,
        bb_std: float = 2.0,
        kc_window: int = 20,
        kc_mult: float = 1.5,
    ) -> Dict[str, pd.Series]:
        """TTM Squeeze / Squeeze Momentum."""
        bb = self.bollinger_bands(close, bb_window, bb_std)
        kc = self.keltner_channel(high, low, close, kc_window, kc_mult)

        squeeze_on = (bb["bb_low"] > kc["kc_low"]) & (bb["bb_high"] < kc["kc_high"])
        squeeze_off = (bb["bb_low"] < kc["kc_low"]) | (bb["bb_high"] > kc["kc_high"])

        # Momentum
        highest_high = high.rolling(20).max()
        lowest_low = low.rolling(20).min()
        mid = (highest_high + lowest_low) / 2
        momentum = close - mid

        return {
            "squeeze_on": squeeze_on,
            "squeeze_off": squeeze_off,
            "momentum": momentum,
            "squeeze_fire": squeeze_off & (momentum > 0),
        }

    def supertrend(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        period: int = 10,
        multiplier: float = 3.0,
    ) -> Dict[str, pd.Series]:
        """SuperTrend Indicator."""
        atr = self.atr(high, low, close, period)
        hl2 = (high + low) / 2

        upper_band = hl2 + multiplier * atr
        lower_band = hl2 - multiplier * atr

        supertrend = pd.Series(index=close.index, dtype=float)
        direction = pd.Series(index=close.index, dtype=int)

        for i in range(len(close)):
            if i == 0:
                supertrend.iloc[i] = upper_band.iloc[i]
                direction.iloc[i] = -1
            else:
                if close.iloc[i] > supertrend.iloc[i-1]:
                    supertrend.iloc[i] = lower_band.iloc[i]
                    direction.iloc[i] = 1
                elif close.iloc[i] < supertrend.iloc[i-1]:
                    supertrend.iloc[i] = upper_band.iloc[i]
                    direction.iloc[i] = -1
                else:
                    supertrend.iloc[i] = supertrend.iloc[i-1]
                    direction.iloc[i] = direction.iloc[i-1]

                # Adjust bands
                if direction.iloc[i] == 1 and lower_band.iloc[i] < supertrend.iloc[i-1]:
                    supertrend.iloc[i] = supertrend.iloc[i-1]
                if direction.iloc[i] == -1 and upper_band.iloc[i] > supertrend.iloc[i-1]:
                    supertrend.iloc[i] = supertrend.iloc[i-1]

        return {
            "supertrend": supertrend,
            "direction": direction,  # 1 = long, -1 = short
            "upper_band": upper_band,
            "lower_band": lower_band,
        }

    def vwap(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
        volume: pd.Series,
    ) -> pd.Series:
        """Volume Weighted Average Price (session)."""
        typical = (high + low + close) / 3
        return (typical * volume).cumsum() / volume.cumsum()

    def pivot_points(
        self,
        high: pd.Series,
        low: pd.Series,
        close: pd.Series,
    ) -> Dict[str, pd.Series]:
        """Classic Pivot Points."""
        pp = (high + low + close) / 3
        r1 = 2 * pp - low
        s1 = 2 * pp - high
        r2 = pp + (high - low)
        s2 = pp - (high - low)
        r3 = high + 2 * (pp - low)
        s3 = low - 2 * (high - pp)

        return {
            "pp": pp, "r1": r1, "s1": s1,
            "r2": r2, "s2": s2,
            "r3": r3, "s3": s3,
        }

    def fibonacci_retracement(
        self,
        high: float,
        low: float,
    ) -> Dict[str, float]:
        """Fibonacci Retracement Levels."""
        diff = high - low
        return {
            "0.0": high,
            "0.236": high - 0.236 * diff,
            "0.382": high - 0.382 * diff,
            "0.5": high - 0.5 * diff,
            "0.618": high - 0.618 * diff,
            "0.786": high - 0.786 * diff,
            "1.0": low,
        }

    def zscore(self, close: pd.Series, window: int = 20) -> pd.Series:
        """Z-Score (mean reversion)."""
        mean = close.rolling(window).mean()
        std = close.rolling(window).std()
        return (close - mean) / std

    def linear_regression(
        self,
        close: pd.Series,
        window: int = 20,
    ) -> Dict[str, pd.Series]:
        """Linear Regression Channel."""
        x = np.arange(window)
        slope = close.rolling(window).apply(
            lambda y: np.polyfit(x, y, 1)[0] if len(y) == window else np.nan,
            raw=True
        )
        intercept = close.rolling(window).apply(
            lambda y: np.polyfit(x, y, 1)[1] if len(y) == window else np.nan,
            raw=True
        )

        lr = slope * (window - 1) + intercept
        std = close.rolling(window).std()

        return {
            "lr": lr,
            "lr_upper": lr + 2 * std,
            "lr_lower": lr - 2 * std,
            "slope": slope,
        }


# ─── INTEGRATION WITH JARVIS INDICATORS ───

def compute_all_ta_indicators(
    df: pd.DataFrame,
    settings: Optional[Settings] = None,
) -> pd.DataFrame:
    """
    Calcola TUTTI gli indicatori TA e li aggiunge al DataFrame.

    Colonne risultanti (esempi):
    - trend_adx, trend_adx_pos, trend_adx_neg
    - trend_macd, trend_macd_signal, trend_macd_diff
    - trend_ema_8, trend_ema_21, trend_ema_50, trend_sma_200
    - trend_ichimoku_a, trend_ichimoku_b, trend_ichimoku_base
    - trend_psar, trend_psar_up, trend_psar_down
    - trend_vortex_pos, trend_vortex_neg
    - momentum_rsi, momentum_stoch, momentum_stoch_signal
    - momentum_williams_r, momentum_roc, momentum_mfi
    - momentum_tsi, momentum_uo, momentum_stoch_rsi
    - volatility_atr, volatility_atr_percent
    - volatility_bb_high, volatility_bb_mid, volatility_bb_low, volatility_bb_width
    - volatility_kc_high, volatility_kc_mid, volatility_kc_low
    - volatility_dc_high, volatility_dc_mid, volatility_dc_low
    - volume_obv, volume_cmf, volume_fi, volume_emv, volume_vpt
    - others_daily_return, others_log_return, others_cumulative_return
    """
    if not HAS_TA:
        raise RuntimeError("ta library non installato: pip install ta")

    # Assicura colonne standard
    required_cols = ["Open", "High", "Low", "Close", "Volume"]
    for col in required_cols:
        if col not in df.columns:
            if col == "Volume":
                df[col] = 0
            else:
                df[col] = df.get("close", df.get("Close", 100))

    # Add all TA features
    df = add_all_ta_features(
        df,
        open="Open",
        high="High",
        low="Low",
        close="Close",
        volume="Volume",
        fillna=True,
    )

    return df


def get_ta_indicator_names() -> Dict[str, List[str]]:
    """Ritorna lista categorizzata di tutti gli indicatori disponibili."""
    return {
        "trend": [
            "adx", "adx_pos", "adx_neg", "aroon_up", "aroon_down", "aroon",
            "macd", "macd_signal", "macd_diff", "ema", "sma", "wma",
