import { NavLink, useLocation } from 'react-router-dom'
import { 
  LayoutDashboard, BarChart2, LineChart, Settings, 
  Zap, Circle, ChevronLeft, ChevronRight 
} from 'lucide-react'
import { useEngineStore } from '@/store/engineStore'
import { useAuthStore } from '@/store/authStore'
import { clsx } from 'clsx'

const navItems = [
  { path: '/dashboard', label: 'Dashboard Live', icon: LayoutDashboard },
  { path: '/backtest', label: 'Backtest & Analytics', icon: BarChart2 },
  { path: '/analytics', label: 'Analisi Avanzate', icon: LineChart },
  { path: '/settings', label: 'Impostazioni', icon: Settings },
] as const

export function Sidebar() {
  const location = useLocation()
  const { running, paused, connected, symbol } = useEngineStore()
  const { logout } = useAuthStore()
  const [collapsed, setCollapsed] = React.useState(false)

  return (
    <aside className={clsx(
      'fixed left-0 top-0 h-screen bg-jarvis-surface border-r border-jarvis-border transition-all duration-300 z-40 flex flex-col',
      collapsed ? 'w-20' : 'w-72'
    )}>
      {/* Brand */}
      <div className={clsx('flex items-center gap-3 p-4 border-b border-jarvis-border transition-all', collapsed && 'justify-center')}>
        <Zap className="w-8 h-8 text-jarvis-primary" />
        {!collapsed && (
          <>
            <span className="font-bold text-xl text-jarvis-text tracking-wide">JARVIS</span>
            <span className="text-xs font-mono text-jarvis-primary px-2 py-0.5 rounded bg-jarvis-primary/10">v20</span>
          </>
        )}
      </div>

      {/* Engine Status */}
      {!collapsed && (
        <div className="p-4 border-b border-jarvis-border">
          <div className="flex items-center gap-3 mb-3">
            <Circle className={clsx('w-2 h-2', running && !paused ? 'text-jarvis-success' : 'text-jarvis-warning')} />
            <span className="text-sm font-medium text-jarvis-text">
              {running ? (paused ? 'IN PAUSA' : 'ATTIVO') : 'FERMO'}
            </span>
          </div>
          <div className="flex items-center gap-2 text-xs text-jarvis-textMuted">
            <Circle className={clsx('w-1.5 h-1.5', connected ? 'text-jarvis-success' : 'text-jarvis-danger')} />
            <span>{connected ? 'WS Connesso' : 'WS Disconnesso'}</span>
            <span className="px-2 py-0.5 rounded bg-jarvis-elevated font-mono">{symbol}</span>
          </div>
        </div>
      )}

      {/* Navigation */}
      <nav className="flex-1 p-3 space-y-1 overflow-y-auto">
        {navItems.map((item) => {
          const isActive = location.pathname === item.path
          const Icon = item.icon
          return (
            <NavLink
              key={item.path}
              to={item.path}
              className={({ isActive }) => clsx(
                'flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all',
                'hover:bg-jarvis-elevated',
                isActive 
                  ? 'bg-jarvis-primary/10 text-jarvis-primary border border-jarvis-primary/20' 
                  : 'text-jarvis-textSecondary hover:text-jarvis-text',
                collapsed && 'justify-center'
              )}
              title={collapsed ? item.label : undefined}
            >
              <Icon className="w-5 h-5 flex-shrink-0" />
              {!collapsed && <span className="font-medium">{item.label}</span>}
            </NavLink>
          )
        })}
      </nav>

      {/* Bottom */}
      <div className={clsx('p-3 border-t border-jarvis-border transition-all', collapsed && 'items-center')}>
        <div className="flex items-center gap-3 mb-3">
          <button
            onClick={() => setCollapsed(!collapsed)}
            className="p-1.5 rounded-lg hover:bg-jarvis-elevated transition-colors"
            aria-label={collapsed ? 'Espandi sidebar' : 'Comprimi sidebar'}
          >
            {collapsed ? <ChevronRight className="w-5 h-5" /> : <ChevronLeft className="w-5 h-5" />}
          </button>
          {!collapsed && (
            <button
              onClick={logout}
              className="flex-1 flex items-center gap-2 px-3 py-2 text-sm text-jarvis-textSecondary hover:text-jarvis-danger hover:bg-jarvis-elevated rounded-lg transition-all"
            >
              <span>Logout</span>
            </button>
          )}
        </div>
      </div>
    </aside>
  )
}

