import { useAuthStore } from '@/store/authStore'

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000'

class ApiClient {
  private getHeaders(): HeadersInit {
    const token = useAuthStore.getState().token
    return {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    }
  }

  async request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
    const res = await fetch(`${API_URL}${endpoint}`, {
      ...options,
      headers: {
        ...this.getHeaders(),
        ...options.headers,
      },
    })

    if (!res.ok) {
      const err = await res.json().catch(() => ({ detail: res.statusText }))
      throw new Error(err.detail || `HTTP ${res.status}`)
    }

    if (res.status === 204) return {} as T
    return res.json()
  }

  // Auth
  login(username: string, password: string) {
    return this.request<{ access_token: string; token_type: string }>('/auth/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ username, password }),
    })
  }

  getMe() {
    return this.request<{ username: string; scopes: string[] }>('/auth/me')
  }

  // Engine
  getEngineStatus() {
    return this.request<any>('/engine/status')
  }

  startEngine(config: any) {
    return this.request<any>('/engine/start', {
      method: 'POST',
      body: JSON.stringify(config),
    })
  }

  stopEngine() {
    return this.request<any>('/engine/stop', { method: 'POST' })
  }

  pauseEngine(pause: boolean) {
    return this.request<any>('/engine/pause', {
      method: 'POST',
      body: JSON.stringify({ pause }),
    })
  }

  switchSymbol(symbol: string) {
    return this.request<any>('/engine/switch_symbol', {
      method: 'POST',
      body: JSON.stringify({ symbol }),
    })
  }

  // Market data
  getQuote(symbol?: string) {
    return this.request<any>(`/market/quote${symbol ? `?symbol=${symbol}` : ''}`)
  }

  getCandles(symbol: string, timeframe: string = 'M1', count: number = 500) {
    return this.request<any>(`/market/candles?symbol=${symbol}&timeframe=${timeframe}&count=${count}`)
  }

  // Decisions
  getLatestDecision() {
    return this.request<any>('/decisions/latest')
  }

  getDecisionHistory(limit: number = 100) {
    return this.request<any>(`/decisions/history?limit=${limit}`)
  }

  // Equity & Risk
  getEquity() {
    return this.request<any>('/equity')
  }

  getRiskSnapshot() {
    return this.request<any>('/risk/snapshot')
  }

  getRiskEngineStatus() {
    return this.request<any>('/risk/engine_status')
  }

  resetCooldown() {
    return this.request<any>('/risk/reset_cooldown', { method: 'POST' })
  }

  resetDay() {
    return this.request<any>('/risk/reset_day', { method: 'POST' })
  }

  // Backtest
  runBacktest(config: any) {
    return this.request<any>('/backtest/run', {
      method: 'POST',
      body: JSON.stringify(config),
    })
  }

  getBacktestStatus(taskId: string) {
    return this.request<any>(`/backtest/status/${taskId}`)
  }

  getBacktestReport(taskId: string) {
    return fetch(`${API_URL}/backtest/report/${taskId}`, {
      headers: this.getHeaders(),
    })
  }

  listBacktests() {
    return this.request<any>('/backtest/list')
  }

  // Optimization
  runOptimization(config: any) {
    return this.request<any>('/optimize/run', {
      method: 'POST',
      body: JSON.stringify(config),
    })
  }

  // Config
  getConfig() {
    return this.request<any>('/config')
  }

  updateConfig(params: Record<string, any>, backup = true) {
    return this.request<any>('/config/update', {
      method: 'POST',
      body: JSON.stringify({ params, backup }),
    })
  }

  // Health
  getHealth() {
    return this.request<any>('/health')
  }

  forceHealthCheck() {
    return this.request<any>('/health/force_check', { method: 'POST' })
  }

  resumeFromCircuitBreaker() {
    return this.request<any>('/health/resume', { method: 'POST' })
  }

  // Logs
  getLogs(level: string = 'INFO', limit: number = 100) {
    return this.request<any>(`/logs?level=${level}&limit=${limit}`)
  }
}

