import { useEngineStore } from '@/store/engineStore'
import { useEngineStatus, useLatestDecision, useEquity, useRiskSnapshot, useHealth } from '@/services/api'
import { TradingChart } from '@/components/charts/TradingChart'
import { EquityChart } from '@/components/charts/EquityChart'
import { 
  TrendingUp, TrendingDown, Minus, AlertTriangle, 
  Shield, Gauge, Zap, Target, Activity, ChevronDown, ChevronUp
} from 'lucide-react'
import { clsx } from 'clsx'
import { Decision, Equity } from '@/types'

interface EquityPoint { time: number; equity: number }

export function Dashboard() {
  const { 
    candles, 
    quote, 
    latestDecision, 
    equity, 
    riskSnapshot, 
    health,
    running,
    paused,
    connected,
  } = useEngineStore()
  
  // React Query data (fallback when WS not connected)
  const { data: engineStatus } = useEngineStatus()
  const { data: decisionData } = useLatestDecision()
  const { data: equityData } = useEquity()
  const { data: riskData } = useRiskSnapshot()
  const { data: healthData } = useHealth()

  // Merge WS + REST data
  const decision = latestDecision || decisionData
  const equityMerged = equity || equityData
  const risk = riskSnapshot || riskData
  const healthStatus = health || healthData

  const [showVolume, setShowVolume] = useState(true)
  const [showEMA8, setShowEMA8] = useState(true)
  const [showEMA21, setShowEMA21] = useState(true)
  const [showEMA50, setShowEMA50] = useState(false)
  const [timeframe, setTimeframe] = useState('M1')
  const [collapsedPanels, setCollapsedPanels] = useState<Record<string, boolean>>({
    metrics: false,
    filters: false,
    bridge: true,
  })

  // Generate mock EMA data for demo (replace with real indicator calculation)
  const emas = useMemo(() => {
    if (candles.size === 0) return undefined
    const tfCandles = candles.get(timeframe) || []
    if (tfCandles.length < 50) return undefined

    const closes = tfCandles.map(c => c.close)
    const ema8 = calculateEMA(closes, 8)
    const ema21 = calculateEMA(closes, 21)
    const ema50 = calculateEMA(closes, 50)
    const vol = tfCandles.map(c => c.volume)

    return { ema8, ema21, ema50, volume: vol }
  }, [candles, timeframe])

  // Equity history for chart (mock for now)
  const equityHistory = useMemo((): EquityPoint[] => {
    if (!equityMerged) return []
    const now = Date.now() / 1000
    const points = []
    let eq = equityMerged.equity - equityMerged.day_pnl
    for (let i = 100; i >= 0; i--) {
      eq += (Math.random() - 0.48) * 50
      points.push({ time: now - i * 3600, equity: eq })
    }
    points.push({ time: now, equity: equityMerged.equity })
    return points
  }, [equityMerged])

  return (
    <div className="h-full flex flex-col gap-6">
      {/* Top Stats Bar */}
