        <div>
          <p className="text-jarvis-textMuted">Regime</p>
          <p className="font-mono capitalize text-jarvis-text">{decision.regime?.toLowerCase() || 'N/A'}</p>
        </div>
      </div>

      <div className="p-3 bg-jarvis-elevated rounded-lg text-sm text-jarvis-textSecondary">
