            <span key={key} className={clsx(
              'px-2 py-0.5 rounded text-xs font-medium',
              passed ? 'bg-jarvis-success/20 text-jarvis-success' : 'bg-jarvis-danger/20 text-jarvis-danger'
            )}>
              {key}: {passed ? '✓' : '✗'}
            </span>
          ))}
        </div>
