      </div>
    </div>
  )
}

function MetricItem({ label, value, positive }: { label: string; value: string; positive?: boolean }) {
  return (
    <div className="p-3 bg-jarvis-elevated rounded-lg">
      <p className="text-xs text-jarvis-textMuted">{label}</p>
      <p className={clsx('font-mono text-jarvis-text', positive !== undefined && (positive ? 'text-jarvis-success' : 'text-jarvis-danger'))}>
        {value}
      </p>
    </div>
  )
}

function FiltersPanel({ decision }: { decision: Decision | null }) {
  const checks = decision?.checks || {}
  
  const filterGroups = {
    'Mercato': ['sessione', 'rollover', 'spread', 'mercato_vivo'],
    'Tecnico': ['adx', 'regime', 'filtri'],
    'Risk': ['cot', 'target', 'killzone'],
  }

  return (
    <div className="space-y-4">
      {Object.entries(filterGroups).map(([group, keys]) => (
        <div key={group} className="space-y-2">
          <p className="text-xs text-jarvis-textMuted uppercase tracking-wide">{group}</p>
          <div className="flex flex-wrap gap-1.5">
            {keys.map(key => (
              <span key={key} className={clsx(
                'px-2 py-1 rounded text-xs font-medium',
                checks[key] ? 'bg-jarvis-success/20 text-jarvis-success' : 'bg-jarvis-danger/20 text-jarvis-danger'
              )}>
                {key}: {checks[key] ? '✓' : '✗'}
              </span>
            ))}
          </div>
        </div>
      ))}
      
      {decision?.filter_blocked_by && (
        <div className="p-3 bg-jarvis-danger/10 border border-jarvis-danger/30 rounded-lg text-jarvis-danger text-sm">
          <strong>Bloccato da:</strong> {decision.filter_blocked_by}
          <p className="mt-1">{decision.reason}</p>
        </div>
      )}
    </div>
  )
}

function BridgePanel({ health }: { health: any }) {
  const checks = health?.checks || {}
  
  return (
    <div className="space-y-3">
      <div className="grid grid-cols-2 gap-3">
        <BridgeMetric label="EA Online" value={checks.feed?.status === 'healthy' ? 'Sì' : 'No'} positive={checks.feed?.status === 'healthy'} />
        <BridgeMetric label="Feed Dati" value={checks.bridge?.status === 'healthy' ? 'OK' : 'Problemi'} positive={checks.bridge?.status === 'healthy'} />
        <BridgeMetric label="Risk Engine" value={checks.risk?.status === 'healthy' ? 'OK' : 'Problemi'} positive={checks.risk?.status === 'healthy'} />
        <BridgeMetric label="Disk Space" value={checks.disk?.status === 'healthy' ? 'OK' : 'Basso'} positive={checks.disk?.status === 'healthy'} />
      </div>
      
      {Object.entries(checks).map(([name, check]: [string, any]) => (
        <div key={name} className="p-3 bg-jarvis-elevated rounded-lg">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-jarvis-text">{name}</span>
            <span className={clsx('px-2 py-0.5 rounded text-xs', check.status === 'healthy' ? 'bg-jarvis-success/20 text-jarvis-success' : 'bg-jarvis-danger/20 text-jarvis-danger')}>
              {check.status}
            </span>
          </div>
          {check.message && <p className="text-xs text-jarvis-textMuted mt-1">{check.message}</p>}
        </div>
      ))}
    </div>
  )
}

function BridgeMetric({ label, value, positive }: { label: string; value: string; positive: boolean }) {
  return (
    <div className="p-3 bg-jarvis-elevated rounded-lg text-center">
      <p className="text-xs text-jarvis-textMuted">{label}</p>
      <p className={clsx('font-mono text-lg', positive ? 'text-jarvis-success' : 'text-jarvis-danger')}>
        {value}
      </p>
    </div>
  )
}

// EMA calculation helper
function calculateEMA(data: number[], period: number): number[] {
  const k = 2 / (period + 1)
  const ema: number[] = []
  let prevEma = data[0]
  
  for (let i = 0; i < data.length; i++) {
    if (i < period - 1) {
      ema.push(NaN)
    } else if (i === period - 1) {
      prevEma = data.slice(0, period).reduce((a, b) => a + b, 0) / period
      ema.push(prevEma)
    } else {
      prevEma = data[i] * k + prevEma * (1 - k)
      ema.push(prevEma)
    }
  }
  return ema
}

