        lastValueVisible: true,
        title: 'EMA 21',
      })
      ema21Ref.current = ema21
    }

    if (showEMA50) {
      const ema50 = chart.addLineSeries({
        color: '#8b5cf6',
        lineWidth: 1,
        lineStyle: 2, // Dashed
        priceLineVisible: false,
        lastValueVisible: true,
        title: 'EMA 50',
      })
      ema50Ref.current = ema50
    }

    // Volume series (separate pane)
    if (showVolume) {
      const volumeSeries = chart.addHistogramSeries({
        color: '#6b7280',
        priceFormat: { type: 'volume' },
        priceScaleId: 'volume',
        base: 0,
      })
      volumeSeriesRef.current = volumeSeries

      chart.applyOptions({
        layout: { background: { type: 'solid', color: '#0a0e17' } },
      })

      // Create volume pane
      const volumePane = chart.addHistogramSeries({
        color: '#6b7280',
        priceFormat: { type: 'volume' },
        priceScaleId: 'volume',
        base: 0,
      })
      // Actually use the same series, just configure price scale
      chart.priceScale('volume').applyOptions({
        scaleMargins: { top: 0.7, bottom: 0 },
        borderVisible: false,
        borderColor: '#374151',
      })
    }

    // Decision markers
    if (decision && decision.action !== 'HOLD') {
      const markerTime = Math.floor(new Date(decision.ts).getTime() / 1000)
      const price = decision.action === 'BUY' 
        ? (decision.sl || quote?.bid || 0) 
        : (decision.sl || quote?.ask || 0)
      
      candleSeries.setMarkers([
        {
          time: markerTime,
          position: decision.action === 'BUY' ? 'belowBar' : 'aboveBar',
          color: decision.action === 'BUY' ? '#10b981' : '#ef4444',
          shape: decision.action === 'BUY' ? 'arrowUp' : 'arrowDown',
          text: `${decision.action} @${decision.confidence.toFixed(0)}%`,
        }
      ])
    }

    // Resize handler
    const resizeObserver = new ResizeObserver(() => {
      chart.resize(containerRef.current!.clientWidth, height)
    })
    resizeObserver.observe(containerRef.current)

    return () => {
      resizeObserver.disconnect()
      chart.remove()
    }
  }, [])

  // Update candle data
  useEffect(() => {
    if (!candleSeriesRef.current || candles.length === 0) return

    const data = candles.map(c => ({
      time: c.time as Time,
      open: c.open,
      high: c.high,
      low: c.low,
      close: c.close,
    }))

    candleSeriesRef.current.setData(data)
  }, [candles])

  // Update volume
  useEffect(() => {
    if (!volumeSeriesRef.current || !volume || volume.length === 0) return

    const data = volume.map((v, i) => ({
      time: candles[i]?.time as Time,
      value: v,
      color: candles[i] && candles[i].close >= candles[i].open ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)',
    }))

    volumeSeriesRef.current.setData(data)
  }, [volume, candles])

  // Update EMAs
  useEffect(() => {
    if (!emas) return

    if (ema8Ref.current && emas.ema8 && showEMA8) {
      const data = emas.ema8.map((v, i) => ({
