    return (
      <div className="text-center py-12">
        <p className="text-jarvis-textMuted mb-4">Nessun risultato Ablation. Esegui per scoprire quali filtri contribuiscono davvero.</p>        <button onClick={onRun} disabled={loading} className="btn-primary gap-2">
