function EquityChart({ data, height }: any) {
  const points = Array.isArray(data) ? data.filter((p: any) => p && Number.isFinite(p.equity)) : []

  if (points.length === 0) {
    return (
      <div
        style={{ height }}
        className="flex flex-col items-center justify-center gap-1 rounded-lg border border-jarvis-border bg-jarvis-elevated/30"
      >
        <span className="text-sm font-medium text-jarvis-text">Nessun dato di equity</span>
        <span className="text-xs text-jarvis-textMuted">L'endpoint /portfolio/equity-curve non ha restituito dati per il range selezionato.</span>
      </div>
    )
  }

  // Simple equity chart using recharts AreaChart
  return (
    <ResponsiveContainer width="100%" height={height}>
      <AreaChart data={points} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
        <defs>
          <linearGradient id="colorPortfolio" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="#2b6bff" stopOpacity={0.3} />
            <stop offset="95%" stopColor="#2b6bff" stopOpacity={0} />
          </linearGradient>
          <linearGradient id="colorBenchmark" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="#6b7280" stopOpacity={0.2} />
            <stop offset="95%" stopColor="#6b7280" stopOpacity={0} />
          </linearGradient>
        </defs>
        <XAxis
          dataKey="time"
          type="number"
          domain={['dataMin', 'dataMax']}
          tickFormatter={(value) => new Date(value).toLocaleDateString('it-IT', { month: 'short', day: 'numeric' })}
          tick={{ fill: '#9ca3af', fontSize: 10 }}
          axisLine={{ stroke: '#374151' }}
          tickLine={{ stroke: '#374151' }}
        />
        <YAxis
          domain={['auto', 'auto']}
          tickFormatter={(value) => `$${(value / 1000).toFixed(0)}k`}
          tick={{ fill: '#9ca3af', fontSize: 10 }}
          axisLine={false}
          tickLine={{ stroke: '#374151' }}
        />
        <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" />
        <Tooltip
          formatter={(value: number) => [`$${value.toLocaleString()}`, 'Equity']}
          contentStyle={{ backgroundColor: '#111827', border: '1px solid #374151', borderRadius: '8px' }}
        />
        <Area
          type="monotone"
          dataKey="equity"
          stroke="#2b6bff"
          strokeWidth={2}
          fillOpacity={1}
          fill="url(#colorPortfolio)"
          connectNulls
          isAnimationActive={false}
        />
        <Area
          type="monotone"
          dataKey="benchmark"
          stroke="#6b7280"
          strokeWidth={1}
          strokeDasharray="5 5"
          fillOpacity={1}
          fill="url(#colorBenchmark)"
          connectNulls
          isAnimationActive={false}
        />
      </AreaChart>
    </ResponsiveContainer>
  )
}

