"""Feed sintetico (random walk + trend) per demo, test e CI senza MT5."""
from __future__ import annotations

import time
from typing import Dict, Optional

import numpy as np

from ..models import Candles, Quote
from .base import DataFeed

_BASE = {"XAUUSD": 2400.0, "EURUSD": 1.085, "GBPUSD": 1.27,
         "USDJPY": 156.0, "BTCUSD": 68000.0}
_DIGITS = {"XAUUSD": 2, "EURUSD": 5, "GBPUSD": 5, "USDJPY": 3, "BTCUSD": 2}


def generate_ohlc(n: int, start: float, vol: float, seed: int = 7,
                  drift: float = 0.0) -> Candles:
    rng = np.random.default_rng(seed)
    steps = rng.normal(drift, vol, n)
    close = start + np.cumsum(steps)
    open_ = np.concatenate([[start], close[:-1]])
    noise = np.abs(rng.normal(0, vol, n))
    high = np.maximum(open_, close) + noise
    low = np.minimum(open_, close) - noise
    t = np.arange(n, dtype=float) * 60
    return Candles(t, open_, high, low, close)


class SyntheticFeed(DataFeed):
    def __init__(self, symbol: str, seed: int = 7, drift: float = 0.0):
        self.symbol = symbol
        self.seed = seed
        self.drift = drift
        self._cache: Dict[str, Candles] = {}

    def connect(self) -> None:
        self._cache.clear()

    def select(self, symbol: str) -> None:
        self.symbol = symbol
        self._cache.clear()

    def _vol(self) -> float:
        return max(_BASE.get(self.symbol, 100.0) * 0.0004, 1e-5)

    def candles(self, timeframe: str, count: int) -> Optional[Candles]:
        key = f"{self.symbol}:{timeframe}:{count}"
        if key not in self._cache:
            mult = {"M1": 1, "M5": 2.2, "M15": 3.9, "H1": 7.7}.get(timeframe, 1)
            self._cache[key] = generate_ohlc(
                count, _BASE.get(self.symbol, 100.0), self._vol() * mult,
                seed=self.seed + len(timeframe), drift=self.drift * mult)
        return self._cache[key]

    def quote(self) -> Quote:
        c = self.candles("M1", 100)
        assert c is not None
        last = float(c.close[-1])
        half = self._vol() * 0.4
        d = _DIGITS.get(self.symbol, 2)
        return Quote(bid=round(last - half, d), ask=round(last + half, d), digits=d)

    def equity(self) -> float:
        return 10_000.0

