import numpy as np


@dataclass
class Candles:
    """Serie OHLC di un timeframe. Colonne numpy allineate."""
    time: np.ndarray
    open: np.ndarray
    high: np.ndarray
    low: np.ndarray
    close: np.ndarray
    volume: Optional[np.ndarray] = None

    def __len__(self) -> int:
        return int(self.close.size)

    def slice(self, end: int, lookback: int) -> "Candles":
        start = max(0, end - lookback)
        return Candles(self.time[start:end], self.open[start:end], self.high[start:end],
                       self.low[start:end], self.close[start:end],
                       self.volume[start:end] if self.volume is not None else None)

    @classmethod
    def from_rows(cls, rows: Sequence[Dict[str, Any]]) -> "Candles":
        def col(k):
            return np.asarray([float(r[k]) for r in rows], dtype=float)
        return cls(np.asarray([r["time"] for r in rows], dtype=float),
                   col("open"), col("high"), col("low"), col("close"))


