import { useEngineStore } from '@/store/engineStore'
import { useStartEngine, useStopEngine, usePauseEngine } from '@/services/api'
import { Play, Pause, Square, RotateCcw, AlertTriangle, Wifi, WifiOff } from 'lucide-react'
import { clsx } from 'clsx'

export function Header() {
  const { running, paused, symbol, connected, health, errorCount } = useEngineStore()
  const startEngine = useStartEngine()
  const stopEngine = useStopEngine()
  const pauseEngine = usePauseEngine()

  const overallHealth = health?.overall || 'unknown'
  const healthColors = {
    healthy: 'text-jarvis-success',
    degraded: 'text-jarvis-warning',
    critical: 'text-jarvis-danger',
    unknown: 'text-jarvis-textMuted',
  }

  return (
    <header className="h-16 bg-jarvis-surface/80 backdrop-blur-sm border-b border-jarvis-border flex items-center justify-between px-6 sticky top-0 z-30">
      <div className="flex items-center gap-6">
        <h1 className="text-xl font-bold text-jarvis-text">JARVIS v20</h1>

        <div className="hidden md:flex items-center gap-4 px-4 py-1.5 rounded-lg bg-jarvis-elevated border border-jarvis-border">
          <span className="text-xs font-medium text-jarvis-textMuted uppercase tracking-wide">Simbolo:</span>
          <span className="font-mono text-jarvis-text">{symbol}</span>
        </div>
      </div>

      <div className="flex items-center gap-4">
        {/* Health Status */}
        <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-lg bg-jarvis-elevated border border-jarvis-border">
          <span className={clsx('w-2 h-2 rounded-full', healthColors[overallHealth])} />
          <span className="text-xs font-medium capitalize text-jarvis-text">{overallHealth}</span>
        </div>

        {/* Connection Status */}
        <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-jarvis-elevated border border-jarvis-border">
          {connected ? (
            <>
              <Wifi className="w-4 h-4 text-jarvis-success" />
              <span className="text-xs text-jarvis-success font-medium">Live</span>
            </>
          ) : (
            <>
              <WifiOff className="w-4 h-4 text-jarvis-danger" />
              <span className="text-xs text-jarvis-danger font-medium">Offline</span>
            </>
          )}
        </div>

        {/* Engine Controls */}
        <div className="flex items-center gap-2">
          {!running ? (
            <button
              onClick={() => startEngine.mutate({ symbol, test_mode: true, feed_type: 'synthetic' })}
              disabled={startEngine.isPending}
              className="btn-primary gap-2"
            >
              <Play className="w-4 h-4" />
              <span className="hidden sm:inline">Avvia</span>
            </button>
          ) : (
            <>
              <button
                onClick={() => pauseEngine.mutate(!paused)}
                disabled={pauseEngine.isPending}
                className={clsx('btn-secondary gap-2', paused && 'bg-jarvis-warning/10 text-jarvis-warning border-jarvis-warning/30')}
              >
                {paused ? <Play className="w-4 h-4" /> : <Pause className="w-4 h-4" />}
                <span className="hidden sm:inline">{paused ? 'Riprendi' : 'Pausa'}</span>
              </button>

              <button
                onClick={() => stopEngine.mutate()}
                disabled={stopEngine.isPending}
                className="btn-danger gap-2"
              >
                <Square className="w-4 h-4" />
                <span className="hidden sm:inline">Stop</span>
              </button>
            </>
          )}

          {/* Error indicator */}
          {errorCount > 0 && (
            <button className="btn-ghost relative text-jarvis-warning p-2">
              <AlertTriangle className="w-5 h-5" />
              <span className="absolute -top-1 -right-1 w-5 h-5 bg-jarvis-danger text-white text-xs rounded-full flex items-center justify-center">
                {errorCount > 9 ? '9+' : errorCount}
              </span>
            </button>
          )}
        </div>
      </div>
    </header>
  )
}

