import { useEffect, useRef, useState } from 'react'
import { createChart, IChartApi, ISeriesApi, ColorType, Time } from 'lightweight-charts'
import { clsx } from 'clsx'
import { Candle, Quote, Decision } from '@/types'

interface TradingChartProps {
  candles: Candle[]
  quote: Quote | null
  decision: Decision | null
  emas?: { ema8: number[]; ema21: number[]; ema50: number[] }
  volume?: number[]
  timeframe: string
  className?: string
  height?: number
  showVolume?: boolean
  showEMA8?: boolean
  showEMA21?: boolean
  showEMA50?: boolean
  onTimeframeChange?: (tf: string) => void
}

const TIMEFRAMES = ['M1', 'M5', 'M15', 'H1', 'H4', 'D1']

export function TradingChart({
  candles,
  quote,
  decision,
  emas,
  volume,
  timeframe,
  className,
  height = 500,
  showVolume = true,
  showEMA8 = true,
  showEMA21 = true,
  showEMA50 = true,
  onTimeframeChange,
}: TradingChartProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const chartRef = useRef<IChartApi | null>(null)
  const candleSeriesRef = useRef<ISeriesApi<'Candlestick'> | null>(null)
  const volumeSeriesRef = useRef<ISeriesApi<'Histogram'> | null>(null)
  const ema8Ref = useRef<ISeriesApi<'Line'> | null>(null)
  const ema21Ref = useRef<ISeriesApi<'Line'> | null>(null)
  const ema50Ref = useRef<ISeriesApi<'Line'> | null>(null)

  // I checkbox della toolbar pilotano la visibilita' delle serie (prima erano controlli morti)
  const [ema8On, setEma8On] = useState(showEMA8)
  const [ema21On, setEma21On] = useState(showEMA21)
  const [ema50On, setEma50On] = useState(showEMA50)
  const [volumeOn, setVolumeOn] = useState(showVolume)

  // Initialize chart
  useEffect(() => {
    if (!containerRef.current) return

    const chart = createChart(containerRef.current, {
      layout: {
        background: { type: ColorType.Solid, color: '#0a0e17' },
        textColor: '#9ca3af',
        fontSize: 11,
        fontFamily: 'JetBrains Mono, monospace',
      },
      grid: {
        vertLines: { color: '#1f2937' },
        horzLines: { color: '#1f2937' },
      },
      crosshair: {
        mode: 1, // Normal
        vertLine: { color: '#374151', width: 1, style: 2, labelBackgroundColor: '#1f2937' },
        horzLine: { color: '#374151', width: 1, style: 2, labelBackgroundColor: '#1f2937' },
      },
      rightPriceScale: {
        borderColor: '#374151',
        scaleMargins: { top: 0.1, bottom: showVolume ? 0.35 : 0.1 },
      },
      timeScale: {
        borderColor: '#374151',
        timeVisible: true,
        secondsVisible: false,
        tickMarkFormatter: (time: Time, tickMarkType: string, locale: string) => {
          const date = new Date((time as number) * 1000)
          if (tickMarkType === 'year') return date.toLocaleDateString(locale, { year: 'numeric' })
          if (tickMarkType === 'month') return date.toLocaleDateString(locale, { month: 'short' })
          if (tickMarkType === 'dayOfMonth') return date.toLocaleDateString(locale, { day: 'numeric', month: 'short' })
          return date.toLocaleTimeString(locale, { hour: '2-digit', minute: '2-digit' })
        },
      },
      handleScroll: { mouseWheel: true, pressedMouseMove: true, horzTouchDrag: true, vertTouchDrag: true },
      handleScale: { axisPressedMouseMove: true, mouseWheel: true, pinch: true },
      localization: { locale: 'it-IT', dateFormat: 'dd/MM/yyyy' },
    })

    chartRef.current = chart

    // Candle series
    const candleSeries = chart.addCandlestickSeries({
      upColor: '#10b981',
      downColor: '#ef4444',
      borderUpColor: '#10b981',
      borderDownColor: '#ef4444',
      wickUpColor: '#10b981',
      wickDownColor: '#ef4444',
      priceFormat: { type: 'price', precision: 2, minMove: 0.01 },
    })
    candleSeriesRef.current = candleSeries

    // EMA series (create sempre, la visibilita' la pilota la toolbar)
    ema8Ref.current = chart.addLineSeries({
      color: '#2b6bff',
      lineWidth: 2,
      priceLineVisible: false,
      lastValueVisible: true,
      visible: ema8On,
      title: 'EMA 8',
    })

    ema21Ref.current = chart.addLineSeries({
      color: '#f59e0b',
      lineWidth: 2,
      priceLineVisible: false,
      lastValueVisible: true,
      visible: ema21On,
      title: 'EMA 21',
    })

    ema50Ref.current = chart.addLineSeries({
      color: '#8b5cf6',
      lineWidth: 1,
      lineStyle: 2, // Dashed
      priceLineVisible: false,
      lastValueVisible: true,
      visible: ema50On,
      title: 'EMA 50',
    })

    // Volume series (pane sovrapposto in fondo al grafico)
    volumeSeriesRef.current = chart.addHistogramSeries({
      color: '#6b7280',
      priceFormat: { type: 'volume' },
      priceScaleId: 'volume',
      base: 0,
      visible: volumeOn,
    })

    chart.priceScale('volume').applyOptions({
      scaleMargins: { top: 0.7, bottom: 0 },
      borderVisible: false,
      borderColor: '#374151',
    })

    // Resize handler
    const resizeObserver = new ResizeObserver(() => {
      chart.resize(containerRef.current!.clientWidth, height)
    })
    resizeObserver.observe(containerRef.current)

    return () => {
      resizeObserver.disconnect()
      chart.remove()
    }
  }, [])

  // Update candle data
  useEffect(() => {
    const series = candleSeriesRef.current
    if (!series) return

    if (!Array.isArray(candles) || candles.length === 0) {
      console.warn(`[TradingChart] nessuna candela ricevuta (timeframe=${timeframe}): grafico vuoto.`)
      return
    }

    const data = candles
      .filter(c => c.time != null && Number.isFinite(c.close))
      .map(c => ({
        time: c.time as Time,
        open: c.open,
        high: c.high,
        low: c.low,
        close: c.close,
      }))

    if (data.length === 0) {
      console.warn('[TradingChart] candele non valide: nessun punto plottato.', candles.slice(0, 3))
      return
    }

    series.setData(data)
  }, [candles, timeframe])

  // Toggle serie dalla toolbar
  useEffect(() => {
    ema8Ref.current?.applyOptions({ visible: ema8On })
    ema21Ref.current?.applyOptions({ visible: ema21On })
    ema50Ref.current?.applyOptions({ visible: ema50On })
    volumeSeriesRef.current?.applyOptions({ visible: volumeOn })
    chartRef.current?.priceScale('').applyOptions({
      scaleMargins: { top: 0.1, bottom: volumeOn ? 0.35 : 0.1 },
    })
  }, [ema8On, ema21On, ema50On, volumeOn])

  // Update decision markers
  useEffect(() => {
    const series = candleSeriesRef.current
    if (!series) return

    const ts = decision ? new Date(decision.ts).getTime() : NaN
    if (!decision || decision.action === 'HOLD' || !Number.isFinite(ts)) {
      series.setMarkers([])
      return
    }

    const isBuy = decision.action === 'BUY'
    series.setMarkers([
      {
        time: Math.floor(ts / 1000) as Time,
        position: isBuy ? 'belowBar' : 'aboveBar',
        color: isBuy ? '#10b981' : '#ef4444',
        shape: isBuy ? 'arrowUp' : 'arrowDown',
        text: `${decision.action} @${decision.confidence.toFixed(0)}%`,
      },
    ])
  }, [decision])

  // Update volume
  useEffect(() => {
    const series = volumeSeriesRef.current
    if (!series || !volume || volume.length === 0) return

    const data = volume
      .map((v, i) => ({ time: candles[i]?.time, value: v }))
      .filter(p => p.time != null && Number.isFinite(p.value))
      .map(p => {
        const c = candles.find(x => x.time === p.time)
        return {
          time: p.time as Time,
          value: p.value as number,
          color: c && c.close >= c.open ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)',
        }
      })

    if (data.length === 0) return
    series.setData(data)
  }, [volume, candles])

  // Update EMAs
  useEffect(() => {
    if (!emas) return

    const toPoints = (values?: number[]) =>
      (values || [])
        .map((v, i) => ({ time: candles[i]?.time, value: v }))
        .filter(p => p.time != null && Number.isFinite(p.value))
        .map(p => ({ time: p.time as Time, value: p.value as number }))

    if (ema8Ref.current) ema8Ref.current.setData(toPoints(emas.ema8))
    if (ema21Ref.current) ema21Ref.current.setData(toPoints(emas.ema21))
    if (ema50Ref.current) ema50Ref.current.setData(toPoints(emas.ema50))
  }, [emas, candles])

  // Update quote price line
  useEffect(() => {
    if (!chartRef.current || !quote) return

    // Update last price marker
    chartRef.current.priceScale('').applyOptions({
      // Could add price line here
    })
  }, [quote])

  const hasCandles = Array.isArray(candles) && candles.length > 0

  return (
    <div className={clsx('w-full', className)}>
      {/* Toolbar */}
      <div className="flex items-center gap-2 mb-2">
        <div className="flex items-center gap-1 bg-jarvis-elevated rounded-lg p-1 border border-jarvis-border">
          {TIMEFRAMES.map(tf => (
            <button
              key={tf}
              onClick={() => onTimeframeChange?.(tf)}
              className={clsx(
                'px-2 py-1 text-xs font-medium rounded transition-colors',
                timeframe === tf
                  ? 'bg-jarvis-primary text-white'
                  : 'text-jarvis-textSecondary hover:text-jarvis-text'
              )}
            >
              {tf}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-1 ml-auto">
          <label className="flex items-center gap-1.5 text-xs text-jarvis-textSecondary cursor-pointer">
            <input
              type="checkbox"
              checked={ema8On}
              onChange={() => setEma8On(v => !v)}
              className="w-4 h-4 accent-jarvis-primary"
            />
            <span style={{ color: '#2b6bff' }}>EMA 8</span>
          </label>
          <label className="flex items-center gap-1.5 text-xs text-jarvis-textSecondary cursor-pointer">
            <input
              type="checkbox"
              checked={ema21On}
              onChange={() => setEma21On(v => !v)}
              className="w-4 h-4 accent-jarvis-warning"
            />
            <span style={{ color: '#f59e0b' }}>EMA 21</span>
          </label>
          <label className="flex items-center gap-1.5 text-xs text-jarvis-textSecondary cursor-pointer">
            <input
              type="checkbox"
              checked={ema50On}
              onChange={() => setEma50On(v => !v)}
              className="w-4 h-4 accent-purple-500"
            />
            <span style={{ color: '#8b5cf6' }}>EMA 50</span>
          </label>
          <label className="flex items-center gap-1.5 text-xs text-jarvis-textSecondary cursor-pointer">
            <input
              type="checkbox"
              checked={volumeOn}
              onChange={() => setVolumeOn(v => !v)}
              className="w-4 h-4 accent-jarvis-textMuted"
            />
            <span>Vol</span>
          </label>
        </div>
      </div>

      {/* Chart host + overlays */}
      <div className="relative">
        <div ref={containerRef} className="w-full" style={{ height }} />

        {/* Empty state: niente dati -> niente riquadro nero ambiguo */}
        {!hasCandles && (
          <div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-1 rounded-lg border border-jarvis-border bg-jarvis-bg/80 pointer-events-none">
            <span className="text-sm font-medium text-jarvis-text">In attesa di dati...</span>
            <span className="text-xs text-jarvis-textMuted text-center px-4">
              Nessuna candela ricevuta per il timeframe {timeframe}.
              <br />
              Avvia il motore o seleziona un altro timeframe.
            </span>
          </div>
        )}

        {/* Current Price */}
        {quote && (
          <div className="absolute top-4 left-4 z-10 flex items-center gap-2 bg-jarvis-bg/90 backdrop-blur px-3 py-1 rounded-lg border border-jarvis-border">
            <span className="text-xs text-jarvis-textMuted">{quote.symbol}</span>
            <span className="font-mono text-lg font-bold text-jarvis-text">{quote.bid.toFixed(2)}</span>
            <span className="text-xs text-jarvis-textMuted">/</span>
            <span className="font-mono text-lg font-bold text-jarvis-text">{quote.ask.toFixed(2)}</span>
            <span className="text-xs px-2 py-0.5 rounded bg-jarvis-elevated">
              Spread: {quote.spread.toFixed(2)}
            </span>
          </div>
        )}

        {/* Decision Badge */}
        {decision && decision.action !== 'HOLD' && (
          <div className="absolute top-4 right-4 z-10">
            <span className={clsx(
              'px-3 py-1 rounded-lg text-xs font-bold',
              decision.action === 'BUY' ? 'bg-green-500/20 text-green-400 border border-green-500/30' : 'bg-red-500/20 text-red-400 border border-red-500/30'
            )}>
              {decision.action} {decision.confidence.toFixed(0)}%
            </span>
          </div>
        )}
      </div>
    </div>
  )
}

