import { Component, ReactNode } from 'react'
import { AlertTriangle, RefreshCw } from 'lucide-react'
import { clsx } from 'clsx'

interface Props {
  children: ReactNode
  fallback?: ReactNode
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void
}

interface State {
  hasError: boolean
  error: Error | null
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, error: null }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error }
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error('[ErrorBoundary] Caught error:', error, errorInfo)
    this.props.onError?.(error, errorInfo)
  }

  handleRetry = () => {
    this.setState({ hasError: false, error: null })
  }

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback
      }
      return (
        <div className={clsx('w-full h-full flex flex-col items-center justify-center gap-4 p-6 rounded-lg border border-jarvis-border bg-jarvis-bg/80')}>
          <AlertTriangle className="w-12 h-12 text-jarvis-warning" />
          <div className="text-center">
            <p className="font-medium text-jarvis-text">Errore nel componente</p>
            <p className="text-xs text-jarvis-textMuted mt-1 max-w-xs">
              {this.state.error?.message || 'Errore sconosciuto'}
            </p>
            <button
              onClick={this.handleRetry}
              className="mt-4 btn-secondary gap-2"
            >
              <RefreshCw className="w-4 h-4" />
              Riprova
            </button>
          </div>
        </div>
      )
    }
    return this.props.children
  }
}

