async request<T>(endpoint: string, options: RequestInit = {}, extra: { allow404?: boolean } = {}): Promise<T | null> {
    const res = await fetch(`${API_URL}${endpoint}`, {
      ...options,
      headers: {
        ...this.getHeaders(),
        ...options.headers,
      },
    })

    if (res.status === 404 && extra.allow404) {
      return null
    }

    if (!res.ok) {
      const err = await res.json().catch(() => ({ detail: res.statusText }))
      throw new Error(err.detail || `HTTP ${res.status}`)
    }

    if (res.status === 204) return {} as T
    return res.json()
  }

