import { useEffect, useRef, useMemo } from 'react'
import { createChart, IChartApi, Time } from 'lightweight-charts'
import { EquityPoint } from '@/types'

interface EquityChartProps {
  data: EquityPoint[]
  height?: number
  className?: string
}

function sanitizeEquityData(data: EquityPoint[]): EquityPoint[] {
  if (data.length === 0) return []
  // Sort by time ascending
  const sorted = [...data].sort((a, b) => a.time - b.time)
  // Deduplicate: keep last value for each timestamp
  const deduped: EquityPoint[] = []
  let lastTime = -1
  for (const p of sorted) {
    if (p.time !== lastTime) {
      deduped.push(p)
      lastTime = p.time
    } else {
      // Same timestamp: overwrite with latest value
      deduped[deduped.length - 1] = p
    }
  }
  // Ensure strictly ascending (lightweight-charts requires this)
  for (let i = 1; i < deduped.length; i++) {
    if (deduped[i].time <= deduped[i - 1].time) {
      deduped[i].time = deduped[i - 1].time + 1
    }
  }
  return deduped
}

export function EquityChart({ data, height = 200, className }: EquityChartProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const chartRef = useRef<IChartApi | null>(null)

  const cleanData = useMemo(() => sanitizeEquityData(data), [data])

  useEffect(() => {
    if (!containerRef.current || cleanData.length === 0) return

    const chart = createChart(containerRef.current, {
      layout: {
        background: { type: 'solid', color: '#0a0e17' },
        textColor: '#9ca3af',
        fontSize: 10,
        fontFamily: 'JetBrains Mono, monospace',
