"""Health monitoring e auto-recovery per JARVIS v20.

Componenti:
- HealthCheck: controlli di salute modulari (feed, bridge, risk, disk, memory)
- Watchdog: monitoraggio continuo con escalation
- AutoRecovery: strategie di recupero automatico per guasti comuni
- MetricsCollector: raccolta metriche per alerting/Prometheus
"""
from __future__ import annotations

import os
import psutil
import shutil
import threading
import time
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from enum import Enum
from pathlib import Path
from typing import Callable, Dict, List, Optional, Any

from .config import Settings
from .logging_setup import get_logger


class HealthStatus(Enum):
    HEALTHY = "healthy"
    DEGRADED = "degraded"
    UNHEALTHY = "unhealthy"
    CRITICAL = "critical"


class RecoveryAction(Enum):
    NONE = "none"
    RECONNECT_FEED = "reconnect_feed"
    RESTART_BRIDGE = "restart_bridge"
    PAUSE_ENGINE = "pause_engine"
    KILL_SWITCH = "kill_switch"
    RESTART_ENGINE = "restart_engine"
    ALERT_ONLY = "alert_only"
    CIRCUIT_BREAKER_PAUSE = "circuit_breaker_pause"


@dataclass
class HealthCheckResult:
    name: str
    status: HealthStatus
    message: str
    timestamp: datetime = field(default_factory=datetime.now)
    metadata: Dict[str, Any] = field(default_factory=dict)
    recovery_action: RecoveryAction = RecoveryAction.NONE

    def is_ok(self) -> bool:
        return self.status in (HealthStatus.HEALTHY, HealthStatus.DEGRADED)


@dataclass
class SystemMetrics:
    cpu_percent: float
    memory_percent: float
    memory_available_mb: float
    disk_free_gb: float
    disk_free_percent: float
    net_connections: int
    thread_count: int
    open_files: int
    timestamp: datetime = field(default_factory=datetime.now)


class HealthCheck:
    """Base class per health check modulari."""

    def __init__(self, name: str, critical: bool = False, interval_sec: float = 30.0):
        self.name = name
        self.critical = critical
        self.interval_sec = interval_sec
        self._last_run: Optional[datetime] = None
        self._last_result: Optional[HealthCheckResult] = None

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        raise NotImplementedError

    def should_run(self) -> bool:
        if self._last_run is None:
            return True
        return (datetime.now() - self._last_run).total_seconds() >= self.interval_sec

    def run(self, context: Dict[str, Any]) -> HealthCheckResult:
        self._last_run = datetime.now()
        try:
            result = self.check(context)
            self._last_result = result
            return result
        except Exception as e:
            result = HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL if self.critical else HealthStatus.UNHEALTHY,
                message=f"Health check exception: {e}",
                recovery_action=RecoveryAction.ALERT_ONLY
            )
            self._last_result = result
            return result


class FeedHealthCheck(HealthCheck):
    """Verifica che il feed dati sia attivo e fornisca dati freschi."""

    def __init__(self, max_age_sec: float = 60.0, **kwargs):
        super().__init__("feed", critical=True, interval_sec=10.0, **kwargs)
        self.max_age_sec = max_age_sec

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        feed = context.get("feed")
        engine = context.get("engine")
        settings = context.get("settings")

        # Usa configurazione se disponibile
        if settings and hasattr(settings, 'max_feed_staleness_sec'):
            self.max_age_sec = settings.max_feed_staleness_sec

        if feed is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Feed non disponibile nel context",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        # Verifica connessione
        if hasattr(feed, 'connected') and not feed.connected:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.UNHEALTHY,
                message="Feed non connesso",
                recovery_action=RecoveryAction.RECONNECT_FEED
            )

        # Verifica dati freschi (ultimo tick)
        if engine and hasattr(engine, 'last_decision') and engine.last_decision:
            age = (datetime.now() - engine.last_decision.ts).total_seconds()
            if age > self.max_age_sec:
                return HealthCheckResult(
                    name=self.name,
                    status=HealthStatus.UNHEALTHY,
                    message=f"Dati vecchi: {age:.0f}s fa (max {self.max_age_sec}s)",
                    metadata={"data_age_sec": age, "max_age_sec": self.max_age_sec},
                    recovery_action=RecoveryAction.CIRCUIT_BREAKER_PAUSE
                )
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.HEALTHY,
                message=f"Feed OK, ultimo dato {age:.1f}s fa",
                metadata={"data_age_sec": age}
            )

        # Nessun dato ancora
        return HealthCheckResult(
            name=self.name,
            status=HealthStatus.DEGRADED,
            message="In attesa primi dati...",
            recovery_action=RecoveryAction.NONE
        )


class BridgeHealthCheck(HealthCheck):
    """Verifica connessione EA MetaTrader 5."""

    def __init__(self, max_age_sec: float = 30.0, **kwargs):
        super().__init__("bridge", critical=True, interval_sec=10.0, **kwargs)
        self.max_age_sec = max_age_sec

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        engine = context.get("engine")
        if engine is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Engine non disponibile",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        bridge = getattr(engine, 'bridge', None)
        if bridge is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Bridge non inizializzato",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        if not getattr(bridge, 'active', False):
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.UNHEALTHY,
                message="Bridge non attivo (file comune non accessibile)",
                recovery_action=RecoveryAction.RESTART_BRIDGE
            )

        last_state = getattr(bridge, 'last_state', None)
        if last_state is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Nessuno stato ricevuto dall'EA",
                recovery_action=RecoveryAction.NONE
            )

        age = last_state.age
        if age > self.max_age_sec:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.UNHEALTHY,
                message=f"EA muto da {age:.1f}s (max {self.max_age_sec}s)",
                metadata={"ea_age_sec": age},
                recovery_action=RecoveryAction.RESTART_BRIDGE
            )

        return HealthCheckResult(
            name=self.name,
            status=HealthStatus.HEALTHY,
            message=f"EA online, latenza {age:.1f}s",
            metadata={"ea_age_sec": age, "equity": last_state.equity}
        )


class RiskHealthCheck(HealthCheck):
    """Verifica risk manager e limiti."""

    def __init__(self, **kwargs):
        super().__init__("risk", critical=True, interval_sec=30.0, **kwargs)

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        engine = context.get("engine")
        if engine is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Engine non disponibile",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        executor = getattr(engine, 'executor', None)
        if executor is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Executor non disponibile",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        risk = getattr(executor, 'risk', None)
        if risk is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Risk manager non disponibile",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        # Verifica kill switch
        if getattr(executor, 'killed', False):
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message=f"KILL SWITCH ATTIVO: {getattr(executor, 'kill_reason', 'sconosciuto')}",
                recovery_action=RecoveryAction.KILL_SWITCH
            )

        # Verifica cap giornaliero
        daily = getattr(risk, 'daily', None)
        if daily:
            settings = context.get("settings")
            if settings:
                base = daily.day_start_equity or risk.equity
                max_daily = -abs(base * settings.max_daily_loss_pct / 100)
                if daily.pnl <= max_daily:
                    return HealthCheckResult(
                        name=self.name,
                        status=HealthStatus.CRITICAL,
                        message=f"Cap perdita giornaliero raggiunto: {daily.pnl:.2f} <= {max_daily:.2f}",
                        recovery_action=RecoveryAction.KILL_SWITCH
                    )

        # Verifica equity minima
        equity = getattr(risk, 'equity', 0)
        settings = context.get("settings")
        if settings:
            extra = settings.extra or {}
            min_equity = float(extra.get("min_equity", 0) or 0)
            if min_equity and equity < min_equity:
                return HealthCheckResult(
                    name=self.name,
                    status=HealthStatus.CRITICAL,
                    message=f"Equity {equity:.2f} sotto minimo {min_equity:.2f}",
                    recovery_action=RecoveryAction.KILL_SWITCH
                )

        return HealthCheckResult(
            name=self.name,
            status=HealthStatus.HEALTHY,
            message=f"Risk OK, equity {equity:.2f}, PnL giorno {daily.pnl if daily else 0:.2f}",
            metadata={"equity": equity, "daily_pnl": daily.pnl if daily else 0}
        )


class DiskHealthCheck(HealthCheck):
    """Verifica spazio disco per data directory."""

    def __init__(self, min_free_gb: float = 1.0, min_free_pct: float = 5.0, **kwargs):
        super().__init__("disk", critical=False, interval_sec=300.0, **kwargs)
        self.min_free_gb = min_free_gb
        self.min_free_pct = min_free_pct

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        data_dir = context.get("data_dir")
        if data_dir is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Data directory non specificata",
                recovery_action=RecoveryAction.NONE
            )

        try:
            usage = shutil.disk_usage(data_dir)
            free_gb = usage.free / (1024**3)
            free_pct = (usage.free / usage.total) * 100

            if free_gb < self.min_free_gb or free_pct < self.min_free_pct:
                return HealthCheckResult(
                    name=self.name,
                    status=HealthStatus.UNHEALTHY,
                    message=f"Spazio disco basso: {free_gb:.1f}GB ({free_pct:.1f}%) liberi",
                    metadata={"free_gb": free_gb, "free_pct": free_pct},
                    recovery_action=RecoveryAction.ALERT_ONLY
                )

            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.HEALTHY,
                message=f"Disco OK: {free_gb:.1f}GB ({free_pct:.1f}%) liberi",
                metadata={"free_gb": free_gb, "free_pct": free_pct}
            )
        except Exception as e:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.UNHEALTHY,
                message=f"Errore controllo disco: {e}",
                recovery_action=RecoveryAction.ALERT_ONLY
            )


class MemoryHealthCheck(HealthCheck):
    """Verifica uso memoria del processo."""

    def __init__(self, max_percent: float = 85.0, **kwargs):
        super().__init__("memory", critical=False, interval_sec=60.0, **kwargs)
        self.max_percent = max_percent

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        try:
            process = psutil.Process()
            mem = process.memory_info()
            mem_percent = process.memory_percent()
            avail = psutil.virtual_memory().available / (1024**2)  # MB

            if mem_percent > self.max_percent:
                return HealthCheckResult(
                    name=self.name,
                    status=HealthStatus.UNHEALTHY,
                    message=f"Memoria processo alta: {mem_percent:.1f}% (RSS: {mem.rss/1024/1024:.0f}MB)",
                    metadata={"mem_percent": mem_percent, "rss_mb": mem.rss/1024/1024, "avail_mb": avail},
                    recovery_action=RecoveryAction.ALERT_ONLY
                )

            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.HEALTHY,
                message=f"Memoria OK: {mem_percent:.1f}% (RSS: {mem.rss/1024/1024:.0f}MB)",
                metadata={"mem_percent": mem_percent, "rss_mb": mem.rss/1024/1024, "avail_mb": avail}
            )
        except Exception as e:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message=f"Errore controllo memoria: {e}",
                recovery_action=RecoveryAction.NONE
            )


class EngineHealthCheck(HealthCheck):
    """Verifica che l'engine sia in esecuzione e risponda."""

    def __init__(self, **kwargs):
        super().__init__("engine", critical=True, interval_sec=15.0, **kwargs)

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        engine = context.get("engine")
        if engine is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Engine non disponibile",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        if not getattr(engine, 'running', False):
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Engine non in esecuzione",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        if getattr(engine, 'paused', False):
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Engine in pausa",
                recovery_action=RecoveryAction.NONE
            )

        # Verifica che il thread sia vivo
        thread = getattr(engine, '_thread', None)
        if thread is not None and not thread.is_alive():
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.CRITICAL,
                message="Thread engine morto",
                recovery_action=RecoveryAction.RESTART_ENGINE
            )

        return HealthCheckResult(
            name=self.name,
            status=HealthStatus.HEALTHY,
            message="Engine in esecuzione",
            metadata={"paused": getattr(engine, 'paused', False)}
        )


class SpreadAnomalyCheck(HealthCheck):
    """Verifica spread anomalo rispetto alla media recente."""

    def __init__(self, max_ratio: float = 3.0, window: int = 50, **kwargs):
        super().__init__("spread_anomaly", critical=False, interval_sec=10.0, **kwargs)
        self.max_ratio = max_ratio
        self.window = window

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        engine = context.get("engine")
        settings = context.get("settings")
        if settings and hasattr(settings, 'max_spread_anomaly_ratio'):
            self.max_ratio = settings.max_spread_anomaly_ratio

        if engine is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Engine non disponibile",
                recovery_action=RecoveryAction.NONE
            )

        # Prendi l'ultimo decision per avere lo spread corrente
        last_decision = getattr(engine, 'last_decision', None)
        if last_decision is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Nessun decision disponibile",
                recovery_action=RecoveryAction.NONE
            )

        current_spread = last_decision.spread
        if current_spread <= 0:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Spread non valido",
                recovery_action=RecoveryAction.NONE
            )

        # Recupera storico spread dal feed se disponibile
        feed = context.get("feed")
        if feed is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.HEALTHY,
                message="Spread check: feed non disponibile per storico",
                recovery_action=RecoveryAction.NONE
            )

        # Prova a ottenere spread storici dal feed (usa candele recenti)
        try:
            # Usa candele M1 per calcolare spread medio recente
            candles = feed.candles("M1", self.window)
            if candles is None or len(candles) < 10:
                return HealthCheckResult(
                    name=self.name,
                    status=HealthStatus.HEALTHY,
                    message="Spread check: storico insufficiente",
                    recovery_action=RecoveryAction.NONE
                )

            # Calcola spread medio dalle candele (high-low come proxy)
            # Nota: questo è un proxy, lo spread reale viene dal quote
            spreads = [c.high[0] - c.low[0] for c in candles[-self.window:]]
            avg_spread = sum(spreads) / len(spreads) if spreads else 0

            if avg_spread <= 0:
                return HealthCheckResult(
                    name=self.name,
                    status=HealthStatus.HEALTHY,
                    message="Spread medio non calcolabile",
                    recovery_action=RecoveryAction.NONE
                )

            ratio = current_spread / avg_spread
            if ratio > self.max_ratio:
                return HealthCheckResult(
                    name=self.name,
                    status=HealthStatus.UNHEALTHY,
                    message=f"Spread anomalo: {current_spread:.5f} vs media {avg_spread:.5f} (ratio {ratio:.1f}x > {self.max_ratio}x)",
                    metadata={"current_spread": current_spread, "avg_spread": avg_spread, "ratio": ratio, "max_ratio": self.max_ratio},
                    recovery_action=RecoveryAction.CIRCUIT_BREAKER_PAUSE
                )

            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.HEALTHY,
                message=f"Spread OK: {current_spread:.5f} (media {avg_spread:.5f}, ratio {ratio:.1f}x)",
                metadata={"current_spread": current_spread, "avg_spread": avg_spread, "ratio": ratio}
            )
        except Exception as e:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message=f"Errore controllo spread: {e}",
                recovery_action=RecoveryAction.NONE
            )


class AckTimeoutCheck(HealthCheck):
    """Verifica timeout ACK consecutivi dall'EA."""

    def __init__(self, max_consecutive: int = 3, **kwargs):
        super().__init__("ack_timeout", critical=True, interval_sec=10.0, **kwargs)
        self.max_consecutive = max_consecutive
        self._consecutive_timeouts = 0

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        engine = context.get("engine")
        settings = context.get("settings")
        if settings and hasattr(settings, 'max_consecutive_ack_timeouts'):
            self.max_consecutive = settings.max_consecutive_ack_timeouts

        if engine is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Engine non disponibile",
                recovery_action=RecoveryAction.NONE
            )

        executor = getattr(engine, 'executor', None)
        if executor is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Executor non disponibile",
                recovery_action=RecoveryAction.NONE
            )

        # Controlla se c'è un lockout attivo (indica che un ordine è stato inviato ma non confermato)
        lock = getattr(executor.cfg, 'lockout_after_order', 15.0)
        sent_at = getattr(executor, '_sent_at', {})
        now = time.time()

        timeout_count = 0
        for symbol, sent_time in sent_at.items():
            if now - sent_time > lock:
                timeout_count += 1

        if timeout_count > 0:
            self._consecutive_timeouts += timeout_count
        else:
            # Reset se non ci sono timeout
            if self._consecutive_timeouts > 0:
                self._consecutive_timeouts = max(0, self._consecutive_timeouts - 1)

        if self._consecutive_timeouts >= self.max_consecutive:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.UNHEALTHY,
                message=f"ACK timeout consecutivi: {self._consecutive_timeouts} (max {self.max_consecutive})",
                metadata={"consecutive_timeouts": self._consecutive_timeouts, "max_allowed": self.max_consecutive},
                recovery_action=RecoveryAction.CIRCUIT_BREAKER_PAUSE
            )

        return HealthCheckResult(
            name=self.name,
            status=HealthStatus.HEALTHY,
            message=f"ACK OK: {self._consecutive_timeouts} timeout consecutivi",
            metadata={"consecutive_timeouts": self._consecutive_timeouts}
        )


class CircuitBreakerCheck(HealthCheck):
    """Circuit breaker aggregato: mette in pausa l'engine se troppe condizioni anomale."""

    def __init__(self, **kwargs):
        super().__init__("circuit_breaker", critical=True, interval_sec=5.0, **kwargs)

    def check(self, context: Dict[str, Any]) -> HealthCheckResult:
        engine = context.get("engine")
        if engine is None:
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.DEGRADED,
                message="Engine non disponibile",
                recovery_action=RecoveryAction.NONE
            )

        # Controlla se l'engine è già in pausa
        if getattr(engine, 'paused', False):
            return HealthCheckResult(
                name=self.name,
                status=HealthStatus.HEALTHY,
                message="Engine già in pausa (circuit breaker non necessario)",
                recovery_action=RecoveryAction.NONE
            )

        # Controlla i risultati degli altri check
        feed_check = None
        spread_check = None
        ack_check = None

        # I risultati degli altri check sono in _last_results dell'health monitor
        # ma qui non abbiamo accesso diretto. Controlliamo direttamente le condizioni.

        # Per ora restituiamo healthy - il circuit breaker vero e proprio
        # viene gestito dall'HealthMonitor che chiama pause_engine
        return HealthCheckResult(
            name=self.name,
            status=HealthStatus.HEALTHY,
            message="Circuit breaker monitoraggio attivo",
            recovery_action=RecoveryAction.NONE
        )


class HealthMonitor:
    """Monitoraggio salute sistema con auto-recovery."""

    def __init__(self, settings: Settings, data_dir: Path,
                 engine=None, feed=None, bridge=None):
        self.settings = settings
        self.data_dir = Path(data_dir)
        self.log = get_logger(self.data_dir)

        # Componenti monitorati
        self.engine = engine
        self.feed = feed
        self.bridge = bridge

        # Health checks registrati
        self.checks: List[HealthCheck] = [
            FeedHealthCheck(),
            BridgeHealthCheck(),
            RiskHealthCheck(),
            DiskHealthCheck(),
            MemoryHealthCheck(),
            EngineHealthCheck(),
            SpreadAnomalyCheck(),
            AckTimeoutCheck(),
            CircuitBreakerCheck(),
        ]

        # Stato
        self._running = False
        self._thread: Optional[threading.Thread] = None
        self._lock = threading.Lock()
        self._last_results: Dict[str, HealthCheckResult] = {}
        self._overall_status = HealthStatus.HEALTHY
        self._callbacks: List[Callable[[Dict[str, HealthCheckResult]], None]] = []

        # Auto-recovery
        self._recovery_cooldown: Dict[str, datetime] = {}
        self._recovery_cooldown_sec = 60.0
        self._max_recoveries_per_hour = 10
        self._recovery_history: List[datetime] = []

        # Metriche
        self._metrics_history: List[SystemMetrics] = []
        self._max_metrics_history = 1000

    def register_callback(self, callback: Callable[[Dict[str, HealthCheckResult]], None]):
        """Registra callback per notifiche cambio stato."""
        self._callbacks.append(callback)

    def start(self):
        """Avvia monitoraggio in background."""
        if self._running:
            return
        self._running = True
        self._thread = threading.Thread(target=self._run_loop, daemon=True)
        self._thread.start()
        self.log.info("Health monitor avviato")

    def stop(self, timeout: float = 5.0):
        """Ferma monitoraggio."""
        self._running = False
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout)
        self.log.info("Health monitor fermato")

    def _run_loop(self):
        while self._running:
            try:
                self._run_checks()
            except Exception as e:
                self.log.exception("Errore in health monitor loop")
            time.sleep(5.0)  # Ciclo base 5 secondi

    def _run_checks(self):
        context = {
            "engine": self.engine,
            "feed": self.feed,
            "bridge": self.bridge,
            "settings": self.settings,
            "data_dir": self.data_dir,
        }

        results = {}
        for check in self.checks:
            if check.should_run():
                result = check.run(context)
                results[check.name] = result
                self._last_results[check.name] = result

        # Aggiorna stato complessivo
        self._update_overall_status()

        # Chiama callback
        for cb in self._callbacks:
            try:
                cb(self._last_results)
            except Exception:
                pass

        # Auto-recovery
        self._attempt_recovery()

        # Raccogli metriche
        self._collect_metrics()

    def _update_overall_status(self):
        statuses = [r.status for r in self._last_results.values()]
        if not statuses:
            self._overall_status = HealthStatus.HEALTHY
        elif HealthStatus.CRITICAL in statuses:
            self._overall_status = HealthStatus.CRITICAL
        elif HealthStatus.UNHEALTHY in statuses:
            self._overall_status = HealthStatus.UNHEALTHY
        elif HealthStatus.DEGRADED in statuses:
            self._overall_status = HealthStatus.DEGRADED
        else:
            self._overall_status = HealthStatus.HEALTHY

    def _attempt_recovery(self):
        """Tenta recovery automatico per check falliti."""
        now = datetime.now()

        # Pulisci history vecchie
        cutoff = now - timedelta(hours=1)
        self._recovery_history = [t for t in self._recovery_history if t > cutoff]

        if len(self._recovery_history) >= self._max_recoveries_per_hour:
            return  # Troppi recovery recenti

        for name, result in self._last_results.items():
            if result.recovery_action == RecoveryAction.NONE:
                continue
            if not result.is_ok():
                # Verifica cooldown per questo check
                last = self._recovery_cooldown.get(name)
                if last and (now - last).total_seconds() < self._recovery_cooldown_sec:
                    continue

                # Esegui recovery
                self._execute_recovery(name, result.recovery_action, result.message)
                self._recovery_cooldown[name] = now
                self._recovery_history.append(now)

    def _execute_recovery(self, check_name: str, action: RecoveryAction, reason: str):
        self.log.warning("Auto-recovery: %s -> %s (%s)", check_name, action.value, reason)

        if action == RecoveryAction.RECONNECT_FEED:
            self._reconnect_feed()
        elif action == RecoveryAction.RESTART_BRIDGE:
            self._restart_bridge()
        elif action == RecoveryAction.PAUSE_ENGINE:
            self._pause_engine()
        elif action == RecoveryAction.KILL_SWITCH:
            self._trigger_kill_switch(reason)
        elif action == RecoveryAction.RESTART_ENGINE:
            self._restart_engine()
        elif action == RecoveryAction.CIRCUIT_BREAKER_PAUSE:
            self._pause_engine()
        elif action == RecoveryAction.ALERT_ONLY:
            pass  # Solo log, già fatto

    def _reconnect_feed(self):
        if self.feed and hasattr(self.feed, 'reconnect'):
            try:
                self.feed.reconnect()
                self.log.info("Feed reconnesso")
            except Exception as e:
                self.log.error("Reconnect feed fallito: %s", e)

    def _restart_bridge(self):
        if self.bridge:
            try:
                # Reset bridge internal state to force re-detection of Common\Files path
                self.bridge._path = None
                time.sleep(1)
                _ = self.bridge.active  # Force reinit
                self.log.info("Bridge riavviato")
            except Exception as e:
                self.log.error("Restart bridge fallito: %s", e)

    def _pause_engine(self):
        if self.engine:
            try:
                self.engine.set_paused(True)
                self.log.info("Engine messo in pausa")
            except Exception as e:
                self.log.error("Pause engine fallito: %s", e)

    def _trigger_kill_switch(self, reason: str):
        if self.engine:
            try:
                executor = getattr(self.engine, 'executor', None)
                if executor:
                    sym = getattr(self.engine.feed, 'symbol', '')
                    executor.force_kill(sym, f"Auto-kill: {reason}", manual=False)
                self.log.error("KILL SWITCH automatico attivato: %s", reason)
            except Exception as e:
                self.log.error("Kill switch fallito: %s", e)

    def _restart_engine(self):
        # Questo richiede supporto esterno (riavvio processo)
        self.log.critical("RESTART ENGINE RICHIESTO - serve intervento esterno")
        # Potremmo impostare un flag per segnalare al processo padre

    def _collect_metrics(self):
        try:
            process = psutil.Process()
            cpu = process.cpu_percent(interval=None)
            mem = process.memory_info()
            mem_pct = process.memory_percent()
            vmem = psutil.virtual_memory()
            disk = shutil.disk_usage(self.data_dir)

            metrics = SystemMetrics(
                cpu_percent=cpu,
                memory_percent=mem_pct,
                memory_available_mb=vmem.available / (1024**2),
                disk_free_gb=disk.free / (1024**3),
                disk_free_percent=(disk.free / disk.total) * 100,
                net_connections=len(process.net_connections()) if hasattr(process, 'net_connections') else 0,
                thread_count=process.num_threads(),
                open_files=len(process.open_files()) if hasattr(process, 'open_files') else 0,
            )
            self._metrics_history.append(metrics)
            if len(self._metrics_history) > self._max_metrics_history:
                self._metrics_history.pop(0)
        except Exception:
            pass

    def get_status(self) -> Dict[str, Any]:
        """Ritorna status completo per UI/API."""
        return {
            "overall": self._overall_status.value,
            "checks": {name: {
                "status": r.status.value,
                "message": r.message,
                "timestamp": r.timestamp.isoformat(),
                "metadata": r.metadata,
                "recovery_action": r.recovery_action.value
            } for name, r in self._last_results.items()},
            "metrics": self._get_latest_metrics(),
            "recovery_count_1h": len(self._recovery_history),
        }

    def _get_latest_metrics(self) -> Optional[Dict[str, Any]]:
        if not self._metrics_history:
            return None
        m = self._metrics_history[-1]
        return {
            "cpu_percent": m.cpu_percent,
            "memory_percent": m.memory_percent,
            "memory_available_mb": m.memory_available_mb,
            "disk_free_gb": m.disk_free_gb,
            "disk_free_percent": m.disk_free_percent,
            "thread_count": m.thread_count,
            "open_files": m.open_files,
            "timestamp": m.timestamp.isoformat(),
        }

    def force_check(self) -> Dict[str, HealthCheckResult]:
        """Esegue tutti i check immediatamente."""
        context = {
            "engine": self.engine,
            "feed": self.feed,
            "bridge": self.bridge,
            "settings": self.settings,
            "data_dir": self.data_dir,
        }
        results = {}
        for check in self.checks:
            result = check.run(context)
            results[check.name] = result
            self._last_results[check.name] = result
        self._update_overall_status()
        return self._last_results


def create_health_monitor(settings: Settings, data_dir: Path,
                           engine=None, feed=None, bridge=None) -> HealthMonitor:
    """Factory per creare HealthMonitor con configurazione standard."""
    return HealthMonitor(settings, data_dir, engine, feed, bridge)

