class Mt5Bridge:
    """Pubblica i comandi di JARVIS e rilegge lo stato riferito dall'EA."""

    def __init__(self, enabled: bool = True, log=None, path: Optional[str] = None,
                 magic: int = DEFAULT_MAGIC, ttl: int = DEFAULT_TTL,
                 state_dir: Optional[Path] = None, test_mode: bool = False):
        self.enabled = enabled
        self.log = log
        self.magic = int(magic)
        self.ttl = int(ttl)
        self.test_mode = test_mode
        self._path: Optional[Path] = None
        self._fallback = Path(path) if path else None
        # La sequenza sopravvive ai riavvii: se ripartisse da 0, l'EA
        # scarterebbe (giustamente) ogni comando come replay finche' non
        # superasse di nuovo l'ultimo seq visto.
        self._seq_file = Path(state_dir) / "bridge_seq.json" if state_dir else None
        self._seq = self._load_seq()
        self.last_command: Optional[Command] = None
        self.last_state: Optional[EaState] = None
        if enabled:
            self._path = _mt5_common_files_path() or self._fallback
            if self._path is None and log is not None and not test_mode:
                log.warning(
                    "Bridge MT5: cartella Common\\Files non trovata. Serve MT5 "
                    "aperto con il pacchetto MetaTrader5 installato, oppure "
                    "extra.mt5_bridge.path nel config. Bridge disattivo: l'EA "
                    "non aprira' nulla (comportamento voluto)."
                )

    # ---------------- percorso ----------------
    @property
    def active(self) -> bool:
        return self.enabled and self._ensure_path() is not None

    def _ensure_path(self) -> Optional[Path]:
        """L'Engine costruisce il bridge prima di ``feed.connect()``.

        Il solo controllo nel costruttore era troppo precoce e lasciava il
        ponte spento per tutta la sessione: qui si riprova a ogni giro.
        """
        if not self.enabled:
            return None
        if self._path is None:
            self._path = _mt5_common_files_path() or self._fallback
            if self._path is not None and self.log is not None:
                self.log.info("Bridge MT5 attivo -> %s", self._path)
        return self._path

    # ---------------- sequenza ----------------
    def _load_seq(self) -> int:
        if self._seq_file is None:
            return int(time.time()) % 1_000_000
        try:
            return int(json.loads(self._seq_file.read_text(encoding="utf-8"))["seq"])
        except Exception:
            return int(time.time()) % 1_000_000

    def _next_seq(self) -> int:

def resolve_data_dir() -> Path:
    """Prima cartella realmente scrivibile: env > cwd > APPDATA > home."""
    candidates: List[Path] = []
    env = os.environ.get("JARVIS_DATA_DIR")
    if env:
        candidates.append(Path(env))
    candidates.append(Path.cwd() / "jarvis_data")
    appdata = os.environ.get("APPDATA")
    if appdata:
        candidates.append(Path(appdata) / "JARVIS")
    candidates.append(Path.home() / "JARVIS")
    for d in candidates:
        try:
            d.mkdir(parents=True, exist_ok=True)
            probe = d / ".write_test"
            probe.write_text("ok", encoding="utf-8")
            probe.unlink()
            os.environ["JARVIS_DATA_DIR"] = str(d)
            return d
        except Exception:
            continue
    return Path.cwd()


