"""Feed MetaTrader5 con auto-reconnect e cache leggera per tick."""
from __future__ import annotations

import time
from typing import Optional

from ..models import Candles, Quote
from .base import DataFeed, FeedError

try:
    import MetaTrader5 as mt5
except ImportError as e:  # pragma: no cover - solo su Windows con MT5
    raise FeedError("MetaTrader5 non installato") from e

_TF = {"M1": mt5.TIMEFRAME_M1, "M5": mt5.TIMEFRAME_M5,
       "M15": mt5.TIMEFRAME_M15, "H1": mt5.TIMEFRAME_H1,
       "H4": mt5.TIMEFRAME_H4, "D1": mt5.TIMEFRAME_D1}


class Mt5Feed(DataFeed):
    def __init__(self, symbol: str, max_tick_age: int = 90):
        self.symbol = symbol
        self.max_tick_age = max_tick_age
        self._connected = False

    def _resolve(self, symbol: str) -> str:
        """Trova il nome reale del simbolo anche con suffissi/alias del broker.

        Es.: XAUUSD -> XAUUSD.m / XAUUSDm / GOLD / #XAUUSD
        """
        if mt5.symbol_info(symbol) is not None:
            return symbol
        try:
            all_syms = [s.name for s in (mt5.symbols_get() or [])]
        except Exception:
            all_syms = []
        target = symbol.upper()
        aliases = {"XAUUSD": ("XAUUSD", "GOLD", "XAUUSDT"),
                   "XAGUSD": ("XAGUSD", "SILVER"),
                   "US30": ("US30", "DJ30", "DOW", "WS30"),
                   "NAS100": ("NAS100", "USTEC", "NDX", "US100"),
                   "GER40": ("GER40", "DE40", "DAX", "GER30")}
        keys = aliases.get(target, (target,))
        # match esatto ignorando case, poi prefisso/contenuto
        for k in keys:
            for name in all_syms:
                if name.upper() == k:
                    return name
        for k in keys:
            for name in all_syms:
                u = name.upper()
                if u.startswith(k) or u.lstrip("#._-").startswith(k):
                    return name
        for k in keys:
            for name in all_syms:
                if k in name.upper():
                    return name
        return symbol

    def connect(self) -> None:
        if not mt5.initialize():
            raise FeedError("MT5 non si connette: apri MetaTrader 5 e fai login")
        resolved = self._resolve(self.symbol)
        if not mt5.symbol_select(resolved, True):
            raise FeedError(
                f"{self.symbol} non disponibile su questo broker. "
                "Aprilo in Market Watch (Ctrl+U) o cambia simbolo nel config."
            )
        self.symbol = resolved
        self._connected = True

    def reconnect(self) -> bool:
        try:
            mt5.shutdown()
        except Exception:
            pass
        time.sleep(2)
        try:
            self.connect()
            return True
        except FeedError:
            return False

    def select(self, symbol: str) -> None:
        resolved = self._resolve(symbol)
        if not mt5.symbol_select(resolved, True):
            raise FeedError(f"Impossibile attivare {symbol}")
        self.symbol = resolved

    def quote(self) -> Quote:
        info = mt5.symbol_info(self.symbol)
        tick = mt5.symbol_info_tick(self.symbol)
        if info is None or tick is None:
            raise FeedError("Dati broker non disponibili")
        if time.time() - int(tick.time) > self.max_tick_age:
            raise FeedError("Mercato chiuso / feed fermo")
        return Quote(bid=round(tick.bid, info.digits), ask=round(tick.ask, info.digits),
                     digits=info.digits)

    def candles(self, timeframe: str, count: int) -> Optional[Candles]:
        rates = mt5.copy_rates_from_pos(self.symbol, _TF[timeframe], 0, count)
        if rates is None or len(rates) == 0:
            return None
        return Candles(rates["time"].astype(float), rates["open"].astype(float),
                       rates["high"].astype(float), rates["low"].astype(float),
                       rates["close"].astype(float))

    def instrument_spec(self):
        from ..risk import InstrumentSpec
        i = mt5.symbol_info(self.symbol)
        if i is None:
            return InstrumentSpec()
        return InstrumentSpec(digits=i.digits, contract_size=i.trade_contract_size,
                              tick_size=i.trade_tick_size or i.point,
                              tick_value=i.trade_tick_value or 1.0,
                              min_lot=i.volume_min, lot_step=i.volume_step,
                              max_lot=i.volume_max)

    def equity(self) -> float:
        acc = mt5.account_info()
        return float(acc.equity) if acc else 10_000.0

    def close(self) -> None:
        try:
            mt5.shutdown()
        except Exception:
            pass
